\begin{document}
\title{\textbf{The Second Sch\"utte Number is Seven}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
A tournament has property \$S_k\$ when every \$k\$-set of vertices is dominated
by a common vertex outside it, and \$f(k)\$ is the least order of such a
tournament. We prove \$f(2) = 7\$ with both bounds machine-checked: the Paley
tournament on \$\mathbb{Z}/7\$ realises the upper bound, and an exhaustive
search over all \$2^{15}\$ tournaments on six vertices realises the lower. The
search is exhaustive by construction rather than by argument, because a
tournament is encoded as the bits of its upper triangle, which makes
antisymmetry a property of the encoding and enumerates each tournament exactly
once.
\end{abstract}

\section{Property \$S_k\$}

\begin{definition}
A tournament on a finite vertex set \$V\$ is an orientation of the complete
graph: for every pair \$u \neq v\$ exactly one of \$u \to v\$, \$v \to u\$ holds.
It has property \$S_k\$ when for every \$S \subseteq V\$ with \$|S| = k\$ there
is a vertex \$v \notin S\$ with \$v \to s\$ for every \$s \in S\$. Write \$f(k)\$
for the least \$|V|\$ admitting such a tournament.
\end{definition}

\section{The encoding}

Let \$n\$ be fixed and index the \$\binom{n}{2}\$ pairs \$i < j\$ by
\[
  \mathrm{pidx}(i,j) \;=\; \frac{i(2n-1-i)}{2} + (j - i - 1),
\]
so that for \$n = 6\$ the pairs receive the indices
\$0\ldots4,\;5\ldots8,\;9\ldots11,\;12,13,\;14\$ in turn. A natural number
\$b < 2^{\binom{n}{2}}\$ then determines a tournament by
\[
  \mathrm{beats}(b,i,j) \;=\;
  \begin{cases}
    \text{bit } \mathrm{pidx}(i,j) \text{ of } b = 1, & i < j,\\[2pt]
    \text{bit } \mathrm{pidx}(j,i) \text{ of } b = 0, & i > j.
  \end{cases}
\]

\begin{lemma}[Antisymmetry is structural]
For all \$b\$ and all \$i < j\$, \$\mathrm{beats}(b,i,j) = \neg\,\mathrm{beats}(b,j,i)\$.
\end{lemma}

\begin{proof}
Both sides read the same bit, one asserting it is \$1\$ and the other that it is
\$0\$, and a bit is one or the other.
\end{proof}

\noindent Consequently \$b \mapsto\$ its tournament is a bijection from
\$\{0,\dots,2^{\binom{n}{2}}-1\}\$ onto the tournaments on \$n\$ labelled
vertices. This is what makes the search below exhaustive: no orientation is
missed and none is visited twice, and no antisymmetry hypothesis is carried
anywhere in the argument.

\section{The upper bound}

\begin{theorem}
The Paley tournament on \$\mathbb{Z}/7\$ has property \$S_2\$, so \$f(2) \le 7\$.
\end{theorem}

\begin{proof}
Set \$i \to j\$ when \$j - i\$ is a non-zero quadratic residue mod \$7\$, that is
when \$j - i \in \{1,2,4\}\$. Since \$-1 \equiv 6\$ is a non-residue, exactly one
of \$j - i\$ and \$i - j\$ lies in \$\{1,2,4\}\$ for \$i \neq j\$, so this is a
tournament. Domination of every pair is a check over the \$7 \cdot 6\$ ordered
pairs, each seeking a common in-neighbour among the remaining five vertices;
all \$42\$ succeed.
\end{proof}

\section{The lower bound}

\begin{theorem}
No tournament on six vertices has property \$S_2\$, so \$f(2) \ge 7\$.
\end{theorem}

\begin{proof}
By the encoding, the tournaments on six labelled vertices are exactly the
\$2^{15} = 32768\$ natural numbers below \$32768\$. For each, test whether every
ordered pair \$i \neq j\$ admits some \$v \notin \{i,j\}\$ with
\$\mathrm{beats}(v,i)\$ and \$\mathrm{beats}(v,j)\$. Every one of the \$32768\$
fails.
\end{proof}

\begin{corollary}
\$f(2) = 7\$.
\end{corollary}

\noindent The same encoding gives \$f(1) = 3\$: the \$3\$-cycle has \$S_1\$, and
both tournaments on two vertices fail, since whoever wins the single edge has
nobody to beat them.

\section{Position}

The general bounds are
\[
  (k+2)\,2^{k-1} - 1 \;\le\; f(k) \;\le\; (1+o(1))\,k^2 2^k \ln 2 ,
\]
the lower bound due to Szekeres and Szekeres and the upper to the probabilistic
method. The lower bound is tight at both values for which \$f\$ is known,
giving \$4 \cdot 2 - 1 = 7\$ and \$5 \cdot 4 - 1 = 19 = f(3)\$, the latter due to
Reid and Parker. For \$k \ge 4\$ the value is unknown; the bounds place \$f(4)\$
above \$47\$.

\section{Formalisation}

The two searches are \texttt{no\_S2\_on\_six} and \texttt{paley7\_has\_S2} in
\texttt{Imscribing/Millennium/Erdos/SchutteTournament.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}. The upper
bound reduces by kernel evaluation; the lower bound uses compiled evaluation and
therefore carries \texttt{ofReduceBool}. Antisymmetry is
\texttt{beats6\_antisymm} and depends on \texttt{propext} alone.

\end{document}
EOF
