\begin{document}
\title{\textbf{Six, and the Two Triangle Dissection Problems}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
Dissecting a triangle into \$n\$ congruent pieces and dissecting it into \$n\$
congruent pieces each similar to the original are different problems, and \$6\$
is the smallest number that separates them. No triangle is rep-\$6\$; the
equilateral triangle nevertheless falls into six congruent \$30\$--\$60\$--\$90\$
pieces, none of them similar to it. We prove both halves, together with the
area identity that forces the similarity ratio to \$1/\sqrt{n}\$ and thereby
supplies the arithmetic of the rep-\$n\$ classification.
\end{abstract}

\section{Two problems}

Let \$T\$ be a triangle in the plane.

\begin{enumerate}
\item[(1)] \emph{rep-\$n\$:} \$T\$ is dissected into \$n\$ mutually congruent
triangles, each similar to \$T\$.
\item[(2)] \emph{congruent-only:} \$T\$ is dissected into \$n\$ mutually
congruent triangles, similarity to \$T\$ not required.
\end{enumerate}

\noindent Question (1) is classified; question (2) is not; and they are not the
same question.

\section{The ratio is forced}

\begin{theorem}[Area identity]
\label{thm:ratio}
If a triangle of area \$A > 0\$ is dissected into \$n\$ pieces each similar to it
with ratio \$r > 0\$, then \$n r^2 = 1\$, so \$r = 1/\sqrt{n}\$.
\end{theorem}

\begin{proof}
A piece similar with ratio \$r\$ has area \$r^2 A\$. The \$n\$ pieces are
disjoint and exhaust \$T\$, so \$n (r^2 A) = A\$. Since \$A \neq 0\$,
cancellation gives \$n r^2 = 1\$; positivity of \$r\$ selects the root.
\end{proof}

\noindent \Cref{thm:ratio} is the whole source of the arithmetic below. The
ratio is rational exactly when \$n\$ is a square, which is why homothety
subdivision --- divide each side into \$k\$ equal parts and draw the parallels
--- settles \$n = k^2\$ for every triangle and settles nothing else. For
non-square \$n\$ the pieces meet the edges of \$T\$ at irrational fractions of
them, and the admissible \$n\$ are cut down accordingly.

\section{The classification, and its least omission}

\begin{theorem}[Snover--Waiveris--Williams]
A triangle is rep-\$n\$ if and only if \$n\$ is a perfect square, a sum of two
positive squares, or three times a square. The three families are realised by,
respectively, an arbitrary triangle, a right triangle with legs in ratio
\$a : b\$, and the \$30\$--\$60\$--\$90\$ triangle.
\end{theorem}

\begin{theorem}
\label{thm:six}
\$6\$ is not of any of those three forms, and every smaller positive integer is.
\end{theorem}

\begin{proof}
For the exclusion, bound each family. A square \$a^2 = 6\$ needs \$a \le 3\$, and
\$1,4,9\$ omit \$6\$. A sum \$a^2 + b^2 = 6\$ with \$a,b \ge 1\$ needs
\$a,b \le 3\$, and the reachable values are \$2,5,8,10,13,18\$. And \$3a^2 = 6\$
needs \$a^2 = 2\$. For the smaller values: \$1 = 1^2\$, \$2 = 1^2 + 1^2\$,
\$3 = 3 \cdot 1^2\$, \$4 = 2^2\$, \$5 = 1^2 + 2^2\$.
\end{proof}

\section{Six congruent pieces, none similar}

\begin{theorem}
\label{thm:equi}
The equilateral triangle admits a dissection into six mutually congruent
triangles, no one of which is similar to it.
\end{theorem}

\begin{proof}
Place the vertices at \$V_0 = (0,0)\$, \$V_1 = (1,0)\$,
\$V_2 = (\tfrac12, \tfrac{\sqrt3}{2})\$, and let \$G = (\tfrac12,
\tfrac{\sqrt3}{6})\$ be the centroid, \$M_{01} = (\tfrac12, 0)\$,
\$M_{12} = (\tfrac34, \tfrac{\sqrt3}{4})\$,
\$M_{02} = (\tfrac14, \tfrac{\sqrt3}{4})\$ the edge midpoints. The three
altitudes cut \$T\$ into the six triangles
\[
  (V_0,M_{01},G),\ (V_1,M_{01},G),\ (V_1,M_{12},G),\
  (V_2,M_{12},G),\ (V_2,M_{02},G),\ (V_0,M_{02},G).
\]
Each has squared side lengths \$\tfrac14,\ \tfrac1{12},\ \tfrac13\$, read off the
coordinates; congruence follows by SSS. Working with squared lengths keeps the
verification polynomial and never extracts a root.

The pieces are right triangles, since \$\tfrac1{12} + \tfrac14 = \tfrac13\$, with
legs in ratio \$1 : \sqrt3\$ --- the \$30\$--\$60\$--\$90\$. The original has all
three squared sides equal to \$1\$. A similarity scales every squared side by a
common factor \$k\$, which would force \$k = \tfrac14\$ and \$k = \tfrac1{12}\$
simultaneously.
\end{proof}

\begin{corollary}
\$6\$ lies outside problem (1) and inside problem (2).
\end{corollary}

\begin{proof}
\Cref{thm:six} with the classification, and \Cref{thm:equi}.
\end{proof}

\section{A third question}

Tilings by triangles that are similar to one another but not congruent form a
third problem, settled by Laczkovich, and the answer there does not transfer to
either of the two above. The distinction that \$6\$ makes visible is between
congruence with similarity to the parent and congruence alone; the distinction
Laczkovich's setting makes is between congruence and similarity.

\section{Formalisation}

\Cref{thm:ratio} is \texttt{rep\_ratio\_sq} and \texttt{rep\_ratio};
\Cref{thm:six} is \texttt{not\_repArith\_six} with
\texttt{six\_is\_least\_excluded}; \Cref{thm:equi} is \texttt{piece\_sides2},
\texttt{pieces\_congruent} and \texttt{piece\_not\_similar\_to\_original}. All
are in \texttt{Imscribing/Millennium/Erdos/TrianglePartition.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}, and all
depend on \texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}
alone.

\end{document}
EOF
