$PRE

\begin{document}
\title{\textbf{Erd\H{o}s--Straus Outside One Congruence Class}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
For every \$n \ge 2\$ with \$n \not\equiv 1 \pmod 4\$, and for every
\$n \equiv 1 \pmod 4\$ divisible by \$3\$, we exhibit positive integers
\$x,y,z\$ with \$4/n = 1/x + 1/y + 1/z\$, by four parametric families each
verified as a polynomial identity. The residues \$n \equiv 1 \pmod 4\$ with
\$3 \nmid n\$ are the entire remaining content of the Erd\H{o}s--Straus
conjecture, and we show the conjecture is equivalent to that class.
\end{abstract}

\section{Statement}

\begin{definition}
A \emph{solution at \$n\$} is a triple of positive integers \$(x,y,z)\$ with
\[
  4xyz \;=\; n\,(yz + xz + xy),
\]
the equation \$4/n = 1/x + 1/y + 1/z\$ cleared of denominators.
\end{definition}

\noindent The conjecture asserts a solution at every \$n \ge 2\$.

\section{Four families}

\begin{theorem}[\$n\$ even]
For \$n = 2m\$ with \$m \ge 1\$, the triple \$(m,\ m+1,\ m(m+1))\$ is a solution.
\end{theorem}

\begin{proof}
\$\tfrac1m + \tfrac1{m+1} + \tfrac1{m(m+1)}
= \tfrac{(m+1) + m + 1}{m(m+1)} = \tfrac{2m+2}{m(m+1)} = \tfrac2m = \tfrac4{2m}\$.
Cleared, \$4m(m+1)\cdot m(m+1) = 2m\big((m+1)m(m+1) + m\,m(m+1) + m(m+1)\big)\$,
a polynomial identity in \$m\$.
\end{proof}

\begin{theorem}[\$n \equiv 3 \pmod 4\$]
For \$n = 4k+3\$, put \$M = n(k+1)\$. The triple \$(k+1,\ M+1,\ M(M+1))\$ is a
solution.
\end{theorem}

\begin{proof}
First \$\tfrac4n - \tfrac1{k+1} = \tfrac{4(k+1) - n}{n(k+1)} = \tfrac1{n(k+1)}
= \tfrac1M\$, using \$4(k+1) - (4k+3) = 1\$. Then split the tail by
\$\tfrac1M = \tfrac1{M+1} + \tfrac1{M(M+1)}\$.
\end{proof}

\begin{theorem}[\$n \equiv 2 \pmod 4\$]
For \$n = 4k+2\$, the triple \$\big(k+1,\ (2k+1)(2k+2),\ (2k+1)(2k+2)\big)\$ is a
solution.
\end{theorem}

\begin{proof}
Here \$n = 2(2k+1)\$, so \$\tfrac4n = \tfrac2{2k+1}\$, and
\$\tfrac2{2k+1} - \tfrac1{k+1} = \tfrac{2(k+1) - (2k+1)}{(2k+1)(k+1)}
= \tfrac1{(2k+1)(k+1)}\$. Halving that into two equal parts gives the two
repeated denominators \$(2k+1)(2k+2)\$.
\end{proof}

\begin{theorem}[\$n \equiv 9 \pmod{12}\$]
\label{thm:twelve}
For \$n = 12k+9\$, the triple \$\big(3k+3,\ 2n(k+1),\ 2n(k+1)\big)\$ is a
solution.
\end{theorem}

\begin{proof}
\$4(3k+3) - n = 12k + 12 - (12k+9) = 3\$, so
\[
  \frac4n - \frac1{3k+3} \;=\; \frac{3}{n(3k+3)} \;=\; \frac{3}{3n(k+1)}
  \;=\; \frac1{n(k+1)} ,
\]
and halving the tail gives the two denominators \$2n(k+1)\$. At \$k = 0\$ this
reads \$\tfrac49 = \tfrac13 + \tfrac1{18} + \tfrac1{18}\$.
\end{proof}

\section{What the families cover}

\begin{theorem}
\label{thm:cover}
Every \$n \ge 2\$ with \$\neg\,(n \equiv 1 \bmod 4 \ \wedge\ 3 \nmid n)\$ has a
solution.
\end{theorem}

\begin{proof}
Split on \$n \bmod 4\$. For \$n \equiv 0\$ and \$n \equiv 2\$ the even family and
the \$4k+2\$ family apply. For \$n \equiv 3\$ the \$4k+3\$ family applies. For
\$n \equiv 1\$ the hypothesis forces \$3 \mid n\$, hence \$n \equiv 9
\pmod{12}\$, and \Cref{thm:twelve} applies.
\end{proof}

\section{The gap is exactly one class}

\begin{theorem}
The Erd\H{o}s--Straus conjecture is equivalent to the assertion that every
\$n \ge 2\$ with \$n \equiv 1 \pmod 4\$ and \$3 \nmid n\$ has a solution.
\end{theorem}

\begin{proof}
One direction is a restriction. For the other, given \$n \ge 2\$, either it lies
in the named class and the assumption applies, or it does not and
\Cref{thm:cover} applies.
\end{proof}

\noindent The remaining class is not a residual: it is where the difficulty of
the problem is concentrated, and it is the class for which no parametric family
is known. Modular covering arguments dispose of \$n\$ in many residue classes
modulo larger moduli; the primes \$n \equiv 1 \pmod{24}\$ resist all of them
currently known.

\section{Formalisation}

The four families are \texttt{solve\_even}, \texttt{solve\_mod4\_3},
\texttt{solve\_mod4\_2} and \texttt{solve\_mod12\_9}, each discharged by
\texttt{ring} on the cleared equation. \Cref{thm:cover} is
\texttt{erdos\_straus\_off\_open\_case} and the equivalence is
\texttt{conjecture\_iff\_open\_case} with \texttt{open\_case\_of\_conjecture}.
All are in \texttt{Imscribing/NumberTheory/ErdosStrausProof.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}, depending on
\texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

\end{document}
EOF
