cat > kac_interval_prime_powers.tex <<EOF
$PRE

\begin{document}
\title{\textbf{An Interval on Which \$\omega(n) > \log\log n\$ Contains No Prime Power}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
Let \$I \subseteq [x,2x]\$ be an interval on which \$\omega(n) > \log\log n\$
holds at every \$n\$. We show \$I\$ contains no prime power beyond \$15\$, so
its length is bounded by the largest prime-power gap it can be placed inside.
The proof is the observation that \$\omega\$ takes the value \$1\$ at a prime
power while \$\log\log\$ passes \$1\$ at \$e^e \approx 15.154\$.
\end{abstract}

\section{The threshold}

\begin{lemma}
\label{lem:sixteen}
\$\log\log 16 > 1\$.
\end{lemma}

\begin{proof}
\$\log 16 = 4 \log 2 > 4 \times 0.6931471803 = 2.7725887212\$, while
\$e < 2.7182818286\$. Hence \$\log 16 > e\$, and applying the logarithm, which
is increasing, gives \$\log\log 16 > \log e = 1\$.
\end{proof}

\begin{lemma}
\label{lem:mono}
For real \$n \ge 16\$, \$\log\log n \ge \log\log 16\$.
\end{lemma}

\begin{proof}
\$\log\$ is increasing and \$\log 16 > 0\$, so \$\log n \ge \log 16 > 0\$ and a
second application preserves the inequality.
\end{proof}

\section{Prime powers are excluded}

\begin{theorem}
\label{thm:excl}
Let \$n \ge 16\$ be a prime power. Then \$\omega(n) \le \log\log n\$; that is,
\$n\$ fails \$\omega(n) > \log\log n\$.
\end{theorem}

\begin{proof}
A prime power has exactly one distinct prime factor, so \$\omega(n) = 1\$. By
\Cref{lem:mono} and \Cref{lem:sixteen}, \$\log\log n \ge \log\log 16 > 1 =
\omega(n)\$.
\end{proof}

\begin{corollary}
\label{cor:interval}
If \$\omega(n) > \log\log n\$ for every \$n \in I\$ and \$\min I \ge 16\$, then
\$I\$ contains no prime power. In particular \$I\$ contains no prime.
\end{corollary}

\section{The consequence for length}

Write \$G(x)\$ for the largest gap between consecutive prime powers in
\$[x,2x]\$. \Cref{cor:interval} places \$I\$ strictly between two consecutive
prime powers, so
\[
  |I| \;\le\; G(x) - 1 .
\]
Prime powers other than primes are sparse --- there are \$O(\sqrt{x})\$ of them
below \$x\$ --- so \$G(x)\$ agrees with the maximal prime gap in \$[x,2x]\$ up to
the rare interference of a square or higher power of a prime, and the bound is
in substance a prime-gap bound.

This locates the difficulty. Unconditionally, maximal prime gaps in \$[x,2x]\$
are known to be at least of order \$\log x \cdot \frac{\log\log x \,
\log\log\log\log x}{\log\log\log x}\$ and are not known to be \$O(\log^2 x)\$;
under the Riemann hypothesis they are \$O(\sqrt{x}\log x)\$, which is far too
weak to be useful at this scale. Any lower bound on \$|I|\$ exceeding the known
prime-gap lower bounds therefore requires a construction that places \$I\$ inside
a long prime-free stretch, and any upper bound on \$|I|\$ beyond
\$G(x) - 1\$ requires more than \Cref{cor:interval}.

\section{Position}

The Erd\H{o}s question asks for the size of the largest such \$I\$ in
\$[x,2x]\$. The Chinese remainder theorem supplies a lower bound by forcing each
\$n + j\$ across a block to carry many small prime factors simultaneously;
Erd\H{o}s conjectured \$|I| \ge (\log x)^k\$ for every fixed \$k\$, which remains
open. Writing \$L = \log x\$, the ratio between the CRT bound \$L/(\log L)^2\$ and
the conjecture \$L^k\$ is \$L^{k-1}(\log L)^2\$: polynomial in \$L\$, and
therefore exponential in \$\log L\$ rather than in \$L\$.

\section{Formalisation}

\Cref{lem:sixteen} is \texttt{loglog\_sixteen\_gt\_one}, \Cref{lem:mono} is
\texttt{loglog\_ge\_of\_ge}, and \Cref{thm:excl} is
