$PRE

\begin{document}
\title{\textbf{Progression-Free Subset Sums Force Distinct Subset Sums}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
Let \$A \subseteq \{1,\dots,N\}\$ with \$|A| = n\$ have the property that its set
of subset sums contains no three-term arithmetic progression. We show the
\$2^n\$ subset sums are then pairwise distinct, whence \$2^n \le nN + 1\$. The
mechanism is that a repeated sum builds a progression out of an intersection
and a union. A base-\$3\$ construction gives \$g_3(n) \le (3^n-1)/2\$ in the
opposite direction, and the exact values \$g_3(n)\$ for \$n \le 5\$ are
\$1,3,8,22,60\$, each closed by a search whose soundness is itself proved.
\end{abstract}

\section{Setting}

For \$A \subseteq \mathbb{N}\$ finite write
\$\Sigma(A) = \{\, \sum_{a \in B} a : B \subseteq A \,\}\$ for its set of subset
sums, the empty subset contributing \$0\$. Call \$A\$ \emph{AP-free} when
\$\Sigma(A)\$ contains no three distinct terms in arithmetic progression, and let
\$g_3(n)\$ be the least \$N\$ for which some AP-free \$A \subseteq \{1,\dots,N\}\$
has \$|A| = n\$.

\section{Distinctness is forced}

\begin{theorem}
\label{thm:distinct}
If \$A\$ is AP-free then the map \$B \mapsto \sum_{a \in B} a\$ is injective on
subsets of \$A\$.
\end{theorem}

\begin{proof}
Suppose \$B \neq C\$ with \$\sum B = \sum C\$. Since subset sums are additive
over the lattice of subsets,
\[
  \textstyle\sum (B \cap C) \;+\; \sum (B \cup C) \;=\; \sum B \;+\; \sum C ,
\]
each element of \$B \cup C\$ being counted once on the right for each of the
sets containing it. Writing \$s = \sum B = \sum C\$, this reads
\$\sum(B \cap C) + \sum(B \cup C) = 2s\$: the three values
\$\sum(B \cap C)\$, \$s\$, \$\sum(B \cup C)\$ form an arithmetic progression, and
all three lie in \$\Sigma(A)\$.

They are distinct. As \$B \neq C\$, at least one of the inclusions
\$B \cap C \subseteq B\$, \$B \subseteq B \cup C\$ is strict, and the entries of
\$A\$ are positive, so the corresponding sums differ; the progression then forces
the third to differ as well. This contradicts AP-freeness.
\end{proof}

\begin{remark}
The empty subset must be admitted for the argument to run: the case
\$B \cap C = \emptyset\$ produces the term \$0\$, which is the first term of the
progression.
\end{remark}

\begin{corollary}
\label{cor:lower}
If \$A \subseteq \{1,\dots,N\}\$ is AP-free with \$|A| = n\$ then
\$2^n \le nN + 1\$, so \$g_3(n) \ge (2^n - 1)/n\$.
\end{corollary}

\begin{proof}
By \Cref{thm:distinct} the \$2^n\$ subset sums are distinct, and each lies in
\$\{0,1,\dots,nN\}\$ since a subset has at most \$n\$ elements each at most \$N\$.
\end{proof}

\section{The base-three construction}

\begin{theorem}
\label{thm:upper}
\$g_3(n) \le (3^n - 1)/2\$.
\end{theorem}

\begin{proof}
Take \$A = \{1, 3, 9, \dots, 3^{n-1}\}\$. A subset sum is the value of a base-\$3\$
numeral with digits in \$\{0,1\}\$. If \$x + z = 2y\$ with \$x,y,z\$ such numerals,
then reading the last digit: both sides are bounded by \$2\$, so no carry occurs
and the digit equation holds on the nose rather than modulo \$3\$. Its solutions
with digits in \$\{0,1\}\$ and the doubled digit in \$\{0,2\}\$ force the three
digits equal; strip and induct. Hence \$x = y = z\$ and no non-trivial
progression exists. The largest element is \$3^{n-1}\$ and the largest subset sum
is \$(3^n-1)/2\$.
\end{proof}

\noindent The absence of carries is the whole content: it converts a congruence
into an equality and lets the induction descend one digit at a time.

\section{Exact small values}

\begin{theorem}
\$g_3(1) = 1\$, \$g_3(2) = 3\$, \$g_3(3) = 8\$, \$g_3(4) = 22\$, \$g_3(5) = 60\$,
witnessed by
\$\{1\}\$, \$\{1,3\}\$, \$\{5,7,8\}\$, \$\{7,19,21,22\}\$ and
\$\{19,52,57,59,60\}\$.
\end{theorem}

\begin{proof}
Each witness is AP-free by inspection of its subset-sum set, giving the upper
bound. For the lower bound one must rule out every \$n\$-subset of
\$\{1,\dots,N-1\}\$. A depth-first walk over increasing tuples suffices, pruned
by the observation that a prefix already carrying a progression cannot be
rescued: the subset sums of a prefix are a subset of those of any extension, and
AP-freeness is inherited downward. Soundness of the pruning is the statement
that the walk reaches every valid configuration, so a negative verdict is a
statement about all subsets rather than about the visited ones.
\end{proof}

\begin{remark}
The ratios \$g_3(n)/3^{n-1}\$ read \$1,\,1,\,0.889,\,0.815,\,0.741\$ and are
decreasing, so \Cref{thm:upper} is not tight beyond \$n = 2\$. The growth
constant \$c\$ with \$g_3(n) = \Theta(c^n)\$ is not known;
\Cref{cor:lower} and \Cref{thm:upper} confine it to \$[2,3]\$.
\end{remark}

\section{Formalisation}

\Cref{thm:distinct} is \texttt{injOn\_sum\_of\_apFree}, \Cref{cor:lower} is
\texttt{two\_pow\_le\_of\_apFree}, and \Cref{thm:upper} rests on
\texttt{no\_three\_ap}. The exact values pair explicit witnesses with
\texttt{no\_config\_of\_search\_false}, whose soundness is \texttt{search\_true}
together with the monotonicity lemmas \texttt{sumsL\_sub} and
\texttt{apFreeL\_mono}. All are in
\texttt{Imscribing/Millennium/Erdos/SumsetAvoidingAP.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}. The case
\$n = 3\$ reduces in the kernel; \$n = 4\$ and \$n = 5\$ use compiled evaluation
and carry \texttt{ofReduceBool}.

\end{document}
EOF
