$PRE

\begin{document}
\title{\textbf{The Lenz Configuration in Four Dimensions}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
Two circles of radius \$1/\sqrt2\$ lying in orthogonal planes of
\$\mathbb{R}^4\$, centred at the origin, have the property that every point of
one is at distance exactly \$1\$ from every point of the other. Splitting \$n\$
points evenly between them gives \$f_4(n) \ge \lfloor n^2/4 \rfloor\$ unit
distances, so the unit-distance problem is quadratic from dimension four
onward.
\end{abstract}

\section{The configuration}

Work in \$\mathbb{R}^4\$ with coordinates \$(x_0,x_1,x_2,x_3)\$ and write
\[
  \alpha(v) = \Big(\tfrac{v_1}{\sqrt2},\ \tfrac{v_2}{\sqrt2},\ 0,\ 0\Big),
  \qquad
  \beta(w) = \Big(0,\ 0,\ \tfrac{w_1}{\sqrt2},\ \tfrac{w_2}{\sqrt2}\Big),
\]
for \$v, w\$ on the unit circle of \$\mathbb{R}^2\$. The images are two circles
of radius \$1/\sqrt2\$ in the orthogonal planes \$x_2 = x_3 = 0\$ and
\$x_0 = x_1 = 0\$.

\begin{theorem}
\label{thm:dist}
For all unit \$v,w\$, \$\ \|\alpha(v) - \beta(w)\| = 1\$.
\end{theorem}

\begin{proof}
The two points have disjoint supports, so
\[
  \|\alpha(v) - \beta(w)\|^2
   = \frac{v_1^2 + v_2^2}{2} + \frac{w_1^2 + w_2^2}{2}
   = \frac12 + \frac12 = 1 .
\]
\end{proof}

\noindent Carrying the circle points as unit vectors of \$\mathbb{R}^2\$ rather
than as angles makes both this computation and the injectivity below read off
the coordinates directly, with no trigonometric identity involved.

\begin{lemma}
\label{lem:inj}
\$\alpha\$ and \$\beta\$ are injective, and their images are disjoint.
\end{lemma}

\begin{proof}
Injectivity is division by \$\sqrt2 \neq 0\$ in each coordinate. For
disjointness, a point of the first image has its \$(x_0,x_1)\$-part on a circle
of radius \$1/\sqrt2\$, while a point of the second has that part at the origin;
were they equal, \$v_1 = v_2 = 0\$, contradicting \$v_1^2 + v_2^2 = 1\$.
\end{proof}

\section{The bound}

\begin{theorem}
\label{thm:lower}
\$f_4(n) \ge \lfloor n^2/4 \rfloor\$, where \$f_d(n)\$ is the maximum number of
unit distances among \$n\$ points of \$\mathbb{R}^d\$.
\end{theorem}

\begin{proof}
Choose finite sets \$S, T\$ of unit vectors of \$\mathbb{R}^2\$ with
\$|S| = \lceil n/2 \rceil\$ and \$|T| = \lfloor n/2 \rfloor\$; the rational
parametrisation \$t \mapsto \big(\tfrac{1-t^2}{1+t^2},
\tfrac{2t}{1+t^2}\big)\$ supplies as many distinct unit vectors as required. Put
\$P = \alpha(S) \cup \beta(T)\$. By \Cref{lem:inj}, \$|P| = |S| + |T| = n\$. By
\Cref{thm:dist} every one of the \$|S|\,|T|\$ cross pairs is at distance \$1\$,
and \$\lceil n/2 \rceil \cdot \lfloor n/2 \rfloor = \lfloor n^2/4 \rfloor\$.
\end{proof}

\noindent The unit-distance graph of \$P\$ contains the complete bipartite graph
on the two circles, which is where the quadratic count comes from; the
construction is due to Lenz.

\section{Position by dimension}

\begin{itemize}
\item \$d = 2\$: \$f_2(n) = n^{1+O(1/\log\log n)}\$ from above by
Szemer\'edi--Trotter, and \$n^{1+c/\log\log n}\$ from below by the lattice
construction. The exponent is not known.
\item \$d = 3\$: bounded above by \$O(n^{3/2})\$ and below by
\$\Omega(n^{4/3}\log\log n)\$. Also open.
\item \$d = 4\$: \Cref{thm:lower} and the matching upper bound
\$\tfrac{n^2}{4}(1 + o(1))\$ settle the order at \$n^2/4\$.
\item \$d \ge 5\$: the same construction, with more room, and the order is again
quadratic.
\end{itemize}

\noindent The change at \$d = 4\$ is the appearance of two orthogonal planes,
which is exactly what \$\mathbb{R}^3\$ cannot supply. In three dimensions two
circles cannot lie in orthogonal planes through a common centre without
intersecting the same two coordinate directions, and the constant-distance
property fails.

\section{Formalisation}

\Cref{thm:dist} is \texttt{dist\_circA\_circB}, \Cref{lem:inj} is
\texttt{circA\_injective}, \texttt{circB\_injective} and
\texttt{circA\_ne\_circB}, and \Cref{thm:lower} is \texttt{lenz\_pairs\_lower}
with \texttt{lenz\_card}, in
\texttt{Imscribing/Millennium/Erdos/UnitDistance.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}. The ambient
space is \texttt{EuclideanSpace} \$\mathbb{R}\$ \texttt{(Fin 4)}, and all results
depend on \texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

\end{document}
EOF
