\begin{document}
\title{\textbf{The Terms of \$\sum (-1)^n n/p_n\$ Are Not Eventually Monotone}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
Let \$a_n = n/p_n\$ with \$p_n\$ the \$n\$-th prime. We prove
\$a_n < a_{n+1}\$ exactly when \$p_n > n\,g_n\$, where \$g_n = p_{n+1} - p_n\$,
and deduce from bounded prime gaps together with \$p_n/n \to \infty\$ that no
tail of \$(a_n)\$ is monotone decreasing. The alternating series test therefore
does not apply to \$\sum (-1)^n a_n\$ at any starting index, although
\$a_n \to 0\$.
\end{abstract}

\section{An exact criterion for a rise}

\begin{theorem}
\label{thm:rise}
Let \$(p_n)\$ be positive with \$p_n < p_{n+1}\$, and put \$a_n = n/p_n\$. Then
\[
  a_n < a_{n+1} \quad\Longleftrightarrow\quad n\,(p_{n+1} - p_n) < p_n .
\]
\end{theorem}

\begin{proof}
Both denominators are positive, so
\$\tfrac{n}{p_n} < \tfrac{n+1}{p_{n+1}}\$ is equivalent to
\$n\,p_{n+1} < (n+1)\,p_n\$. Substituting \$p_{n+1} = p_n + g_n\$ turns the left
side into \$n p_n + n g_n\$ and the right into \$n p_n + p_n\$, and cancelling
\$n p_n\$ leaves \$n g_n < p_n\$.
\end{proof}

\noindent No analysis enters. The comparison of two ratios is a comparison of
two products, and the gap appears by substitution.

\begin{corollary}
\label{cor:small}
If \$g_n \le B\$ and \$nB < p_n\$ then \$a_n < a_{n+1}\$.
\end{corollary}

\section{No monotone tail}

\begin{theorem}
\label{thm:nomono}
Suppose the gaps are bounded infinitely often --- there is \$B\$ such that for
every \$N\$ some \$n \ge N\$ has \$g_n \le B\$ --- and \$p_n/n \to \infty\$. Then
there is no \$N\$ with \$a_{n+1} \le a_n\$ for all \$n \ge N\$.
\end{theorem}

\begin{proof}
Fix such an \$N\$ for contradiction. Superlinearity applied at the constant \$B\$
gives \$M\$ with \$nB < p_n\$ for all \$n \ge M\$. Bounded gaps applied at
\$\max(N,M)\$ give some \$n \ge \max(N,M)\$ with \$g_n \le B\$. By
\Cref{cor:small}, \$a_n < a_{n+1}\$, contradicting the assumed decrease at that
\$n\$.
\end{proof}

\noindent Both hypotheses hold for the primes: the first by the bounded gaps
theorem of Zhang and Maynard, which gives \$g_n \le 246\$ infinitely often; the
second by the prime number theorem, under which \$p_n \sim n \log n\$ and
\$p_n / n \to \infty\$.

\section{Twin primes, and the smallest instance}

\begin{corollary}
At any index \$n\$ with \$g_n = 2\$ and \$p_n > 2n\$, the term rises.
\end{corollary}

\begin{proof}
\Cref{cor:small} with \$B = 2\$.
\end{proof}

\noindent Indexing the primes from \$p_1 = 2\$, the smallest such index is
\$n = 13\$: there \$p_{13} = 41\$, \$p_{14} = 43\$, and \$41 > 26\$, giving
\[
  a_{13} = \tfrac{13}{41} \approx 0.3171 \;<\; \tfrac{14}{43} \approx 0.3256 = a_{14}.
\]

\section{Consequence for the series}

The alternating series test requires the magnitudes to tend to zero and to be
eventually monotone decreasing. The first hypothesis holds: \$a_n \to 0\$, since
\$p_n \sim n\log n\$. \Cref{thm:nomono} denies the second on every tail. Hence
the convergence of \$\sum (-1)^n n/p_n\$, if it holds, must come from
cancellation between paired terms, which is a statement about the sequence of
gaps rather than about the magnitudes alone. Terms tending to zero are not
sufficient for a series whose signs are imposed externally rather than arising
from monotone decrease.

\section{Formalisation}

\Cref{thm:rise} is \texttt{rise\_iff}, \Cref{cor:small} is
\texttt{rise\_of\_small\_gap}, and \Cref{thm:nomono} is
\texttt{not\_eventually\_monotone}, in
\texttt{Imscribing/Classical/ErdosProblem16.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}. The two
inputs are carried as hypotheses \texttt{BoundedGaps} and \texttt{SuperLinear}
rather than assumed silently, and every result depends on \texttt{propext},
\texttt{Classical.choice} and \texttt{Quot.sound}.

\end{document}
EOF
