$PRE

\begin{document}
\title{\textbf{The Averaged Representation Count of an Additive Basis}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
For \$A \subseteq \mathbb{N}\$ with representation function
\$r_A(n) = \#\{(a,b) \in A^2 : a+b = n\}\$, the partial sum
\$\sum_{n<N} r_A(n)\$ counts exactly the pairs from \$A\$ summing below \$N\$, and
is therefore at most \$|A \cap [0,N)|^2\$. If \$A\$ is a basis of order two then
the same sum is at least \$N - N_0\$, giving the square-root density bound
\$N - N_0 \le |A \cap [0,N)|^2\$. The two bounds squeeze the average
\$N^{-1}\sum_{n<N} r_A(n)\$ between a constant and \$|A \cap [0,N)|^2/N\$, so a
basis of square-root density has bounded average.
\end{abstract}

\section{The partial sum is a pair count}

\begin{definition}
\$r_A(n) = \#\{(a,b) \in A \times A : a + b = n\}\$, and
\$\mathrm{avg}_A(N) = N^{-1}\sum_{n<N} r_A(n)\$.
\end{definition}

\begin{theorem}
\label{thm:count}
\$\displaystyle \sum_{n<N} r_A(n) \;=\;
 \#\{(a,b) \in A^2 : a < N,\ b < N,\ a+b < N\}\$.
\end{theorem}

\begin{proof}
Fibre the right-hand set over the map \$(a,b) \mapsto a+b\$, which lands in
\$\{0,\dots,N-1\}\$ by the third condition. The fibre over \$n\$ consists of the
pairs with \$a+b = n\$ and both entries in \$A\$; the side conditions
\$a,b < N\$ are implied by \$a + b = n < N\$, so the fibre is counted by
\$r_A(n)\$.
\end{proof}

\begin{corollary}
\label{cor:upper}
\$\displaystyle \sum_{n<N} r_A(n) \;\le\; |A \cap [0,N)|^2\$.
\end{corollary}

\begin{proof}
Every counted pair has both entries in \$A \cap [0,N)\$, so the set injects into
the square of that set.
\end{proof}

\section{What a basis forces}

\begin{definition}
\$A\$ is a \emph{basis of order two} when there is \$N_0\$ with \$n \in A + A\$
for every \$n \ge N_0\$.
\end{definition}

\begin{theorem}
\label{thm:sqrt}
If \$A\$ is a basis of order two with threshold \$N_0\$ and \$N \ge N_0\$ then
\[
  N - N_0 \;\le\; |A \cap [0,N)|^2 .
\]
\end{theorem}

\begin{proof}
Each \$n\$ with \$N_0 \le n < N\$ has a representation, so \$r_A(n) \ge 1\$, and
summing over those \$N - N_0\$ values gives
\$N - N_0 \le \sum_{n<N} r_A(n)\$. Apply \Cref{cor:upper}.
\end{proof}

\noindent So a basis of order two has at least \$\sqrt{N - N_0}\$ elements below
\$N\$: square-root density is necessary. \Cref{thm:sqrt} is the useful
consequence of the basis hypothesis, and it is a statement about the size of
\$A\$, not about the size of \$r_A\$.

\section{The average is bounded, not unbounded}

\begin{theorem}
\label{thm:avg}
If \$|A \cap [0,N)| \le C\sqrt{N}\$ then \$\mathrm{avg}_A(N) \le C^2\$.
\end{theorem}

\begin{proof}
By \Cref{cor:upper}, \$\sum_{n<N} r_A(n) \le |A \cap [0,N)|^2 \le C^2 N\$;
divide by \$N\$.
\end{proof}

\begin{corollary}
A basis of order two whose counting function is \$O(\sqrt N)\$ has bounded
averaged representation count. In particular the basis hypothesis alone implies
neither \$\mathrm{avg}_A(N) \to \infty\$ nor any growth rate for it.
\end{corollary}

\noindent The lower side is equally rigid: by \Cref{thm:sqrt},
\$\mathrm{avg}_A(N) \ge 1 - N_0/N\$, so the average is pinned near \$1\$ from
below for every basis. The average is therefore the wrong statistic to look at.

\section{Where the Erd\H{o}s--Fuchs theorem lives}

The Erd\H{o}s--Fuchs theorem concerns the error term rather than the average: it
asserts that
\[
  \sum_{n \le N} r_A(n) \;=\; cN + o\!\left(N^{1/4} (\log N)^{-1/2}\right)
\]
is impossible for \$c > 0\$. The partial sums cannot hug a linear function that
closely, however \$A\$ is chosen. This is compatible with, and independent of,
the bounds above: \Cref{thm:avg} constrains the leading coefficient's
magnitude, while Erd\H{o}s--Fuchs constrains the fluctuation around it.

\section{Formalisation}

\Cref{thm:count} is \texttt{sum\_repr\_eq\_card\_pairs}, proved by fibring with
\texttt{Finset.card\_eq\_sum\_card\_fiberwise}; \Cref{cor:upper} is
\texttt{sum\_repr\_le\_card\_sq}; \Cref{thm:sqrt} is
\texttt{basis\_sqrt\_density}; and \Cref{thm:avg} is
\texttt{avg\_bounded\_of\_sqrt\_density}. All are in
\texttt{Imscribing/Millennium/ProofModules/ErdosFuchs.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}, depending on
\texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

\end{document}
EOF
