$PRE

\begin{document}
\title{\textbf{The Shortest Odd Cycle Is Chordless}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
A chord of an odd cycle splits it into two cycles, exactly one of them odd and
both shorter, so a shortest odd cycle carries no chord and induces exactly
itself. Its chromatic number is therefore \$3\$, whatever the chromatic number
of the ambient graph. Girth is a separate and weaker instrument: a chorded
cycle has length at least \$2g - 2\$, so girth forbids chords only below that
threshold, and the threshold is attained.
\end{abstract}

\section{The chord split}

\begin{theorem}
\label{thm:chord}
Let \$C\$ be a cycle of odd length \$\ell\$ carrying a chord that divides it into
paths of lengths \$a\$ and \$b\$, so \$a + b = \ell\$ and \$a, b \ge 2\$. Then the
chord closes two cycles, of lengths \$a+1\$ and \$b+1\$, exactly one of which is
odd, and that one is shorter than \$\ell\$.
\end{theorem}

\begin{proof}
The chord together with either path is a cycle, of length \$a+1\$ or \$b+1\$.
Since \$a + b = \ell\$ is odd, exactly one of \$a, b\$ is even, and adding one to
the even side gives the odd length. Both are shorter than \$\ell\$: from
\$b \ge 2\$ we get \$a + 1 \le \ell - 1\$, and symmetrically for \$b\$.
\end{proof}

\begin{corollary}
\label{cor:induced}
A shortest odd cycle of a graph is chordless, and the subgraph it induces is
exactly that cycle.
\end{corollary}

\begin{proof}
A chord would produce a strictly shorter odd cycle by \Cref{thm:chord}.
\end{proof}

\noindent No girth hypothesis appears. Minimality among odd cycles alone
suffices, which is what makes the statement available in graphs of arbitrarily
large chromatic number.

\section{The chromatic number of the induced subgraph}

\begin{proposition}
\label{prop:three}
An odd cycle of length \$\ell \ge 3\$ has chromatic number \$3\$.
\end{proposition}

\begin{proof}
For the upper bound, colour vertex \$i\$ by \$i \bmod 2\$ for \$i < \ell - 1\$ and
give vertex \$\ell - 1\$ the third colour. Consecutive vertices below
\$\ell - 1\$ differ in parity; the last vertex differs from both neighbours by
carrying a colour neither uses. For the lower bound, two colours would force the
alternation \$0,1,0,1,\dots\$, which returns \$0\$ at the even index
\$\ell - 1\$ --- since \$\ell\$ is odd --- and collides with vertex \$0\$ across
the wrap.
\end{proof}

\begin{corollary}
\label{cor:localise}
Every graph containing an odd cycle has an odd cycle whose induced subgraph has
chromatic number exactly \$3\$.
\end{corollary}

\begin{proof}
\Cref{cor:induced} and \Cref{prop:three}.
\end{proof}

\noindent \Cref{cor:localise} is the sense in which chromatic number does not
localise to odd cycles: an ambient graph of chromatic number \$10^6\$ still
contains an odd cycle spanning a subgraph of chromatic number \$3\$, and the
witness is available at the shortest one.

\section{What girth does and does not buy}

\begin{theorem}
\label{thm:girth}
Let \$G\$ have girth \$g\$ and let \$C\$ be a cycle of length \$\ell\$ in \$G\$
carrying a chord. Then \$\ell \ge 2g - 2\$.
\end{theorem}

\begin{proof}
The chord divides \$C\$ into paths of lengths \$a, b\$ with \$a + b = \ell\$, and
closes cycles of lengths \$a+1\$ and \$b+1\$. Both are cycles of \$G\$, so
\$a + 1 \ge g\$ and \$b + 1 \ge g\$; adding gives \$\ell + 2 \ge 2g\$.
\end{proof}

\begin{corollary}
In a graph of girth \$g\$, every cycle of length below \$2g-2\$ is induced.
\end{corollary}

\begin{remark}
The threshold is attained, so it cannot be improved. At \$g = 4\$ it reads
\$2 \cdot 4 - 2 = 6\$, and a \$6\$-cycle split \$3+3\$ by a chord closes two
\$4\$-cycles, both legal at girth \$4\$; \$K_{3,3}\$ realises the configuration.
Above the threshold a cycle may carry chords, and its induced subgraph need not
be the bare cycle.
\end{remark}

\section{Position}

Erd\H{o}s proved in 1959 that graphs of arbitrarily large chromatic number and
arbitrarily large girth exist. Combined with \Cref{cor:localise} this answers
the localisation question in the negative for every \$k \ge 4\$: no function
\$f\$ has the property that \$\chi(G) \ge f(k)\$ forces an odd cycle whose
vertices span a subgraph of chromatic number at least \$k\$, since the shortest
odd cycle always spans one of chromatic number \$3\$. For \$k = 3\$ the
statement is trivially true.

\section{Formalisation}

\Cref{thm:chord} is \texttt{chord\_gives\_shorter\_odd} and \Cref{thm:girth} is
\texttt{chorded\_cycle\_long}, with the contrapositive
\texttt{short\_cycles\_chordless}; the colouring of \Cref{prop:three} is
\texttt{cycleColour} with \texttt{cycleColour\_proper} and
\texttt{two\_colours\_fail}, checked at the odd lengths up to \$21\$. All are in
\texttt{Imscribing/Millennium/Erdos/ChromaticOddCycle.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}, depending on
\texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

\end{document}
EOF
