\begin{document}
\title{\textbf{Thick Sets, Syndetic Sets, and the Density of a Lacunary Difference Set}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
Bounded gaps and arbitrarily long runs are complementary: a set is thick exactly
when its complement is not syndetic. We prove the duality, prove that a thick
set has upper Banach density one rather than zero, and show that a syndetic set
has positive \emph{lower} density. At the opposite extreme, for the lacunary set
\$\{2^n\}\$ every non-zero difference pins both exponents, so no non-zero
difference recurs and the difference set is \$\{0\}\$.
\end{abstract}

\section{Two notions}

\begin{definition}
\$S \subseteq \mathbb{Z}\$ is \emph{syndetic} when there is \$N \ge 1\$ such that
every window \$\{x, x+1, \dots, x+N-1\}\$ meets \$S\$; it is \emph{thick} when for
every \$N\$ some window of length \$N\$ is contained in \$S\$.
\end{definition}

\begin{theorem}[Duality]
\label{thm:dual}
\$S\$ is thick if and only if \$\mathbb{Z} \setminus S\$ is not syndetic.
\end{theorem}

\begin{proof}
Suppose \$S\$ thick and the complement syndetic with constant \$N\$. Thickness
gives a window of length \$N\$ inside \$S\$; syndeticity gives a point of the
complement in that window. The point lies in both \$S\$ and its complement.

Conversely suppose the complement is not syndetic. For \$N = 0\$ thickness is
vacuous. For \$N \ge 1\$, were no window of length \$N\$ contained in \$S\$, every
window of length \$N\$ would meet the complement, making it syndetic with
constant \$N\$.
\end{proof}

\section{Density of a thick set}

\begin{definition}
Write \$\mathrm{cnt}_S(x,N) = \#\{0 \le i < N : x + i \in S\}\$. Say \$S\$ has
\emph{upper Banach density zero} when for every \$c > 0\$ there is \$N \ge 1\$
with \$\mathrm{cnt}_S(x,N) < cN\$ for every \$x\$.
\end{definition}

\begin{theorem}
\label{thm:thickdense}
A thick set does not have upper Banach density zero.
\end{theorem}

\begin{proof}
Apply the definition at \$c = 1\$ to obtain \$N \ge 1\$ with
\$\mathrm{cnt}_S(x,N) < N\$ for every \$x\$. Thickness supplies \$x\$ with the
whole window inside \$S\$, so \$\mathrm{cnt}_S(x,N) = N\$.
\end{proof}

\noindent In fact the supremum of window densities is \$1\$: a thick set fills a
window of every length completely. Thickness is a density-one phenomenon, not a
density-zero one.

\begin{proposition}
\label{prop:synlower}
A syndetic set with constant \$N\$ has \$\mathrm{cnt}_S(x,N) \ge 1\$ for every
\$x\$, so its lower Banach density is at least \$1/N\$.
\end{proposition}

\begin{proof}
Immediate from the definition: the window from \$x\$ of length \$N\$ meets \$S\$.
\end{proof}

\noindent The contrast is worth stating. Syndeticity bounds every window from
below; thickness bounds one window per length from above. They are not two
strengths of the same notion.

\section{Recurrence and the lacunary extreme}

\begin{definition}
\$D(A) = \{ d : |A \cap (A - d)| = \infty \}\$, the differences occurring
infinitely often in \$A\$.
\end{definition}

\begin{theorem}
\label{thm:lac}
Let \$A = \{2^n : n \ge 0\}\$ and let \$d > 0\$. If \$2^a - 2^b = d\$ with
\$b < a\$ then \$2^b \le d\$ and \$2^a \le 2d\$. Consequently each non-zero \$d\$
is realised by only finitely many pairs, and \$D(A) = \{0\}\$.
\end{theorem}

\begin{proof}
Factor \$d = 2^b(2^{a-b} - 1)\$. Since \$a > b\$ the cofactor is at least \$1\$,
so \$2^b \le d\$; and then \$2^a = d + 2^b \le 2d\$. Both exponents are bounded
by \$d\$, leaving finitely many pairs. As \$0 \in D(A)\$ trivially and no other
\$d\$ recurs, \$D(A) = \{0\}\$.
\end{proof}

\begin{corollary}
\$D(A)\$ is not syndetic for \$A = \{2^n\}\$: a single point has unbounded gaps.
\end{corollary}

\section{Position}

For \$A\$ of positive upper Banach density, the Furstenberg correspondence
principle transports \$A\$ to a measure-preserving system in which Poincar\'e
recurrence applies, and \$D(A)\$ is syndetic; it contains a Bohr\$_0\$ set. The
converse fails, so positive density is sufficient and not necessary. A
counterexample to the converse must be a set of density zero whose difference
set nonetheless has bounded gaps --- by \Cref{thm:thickdense} a thick set is
not one, since thickness supplies density one rather than zero. Locating a
complete characterisation of the sets \$A\$ for which \$D(A)\$ is syndetic
remains open.

\section{Formalisation}

\Cref{thm:dual} is \texttt{thick\_iff\_compl\_not\_syndetic},
\Cref{thm:thickdense} is \texttt{thick\_not\_banach\_zero} with
\texttt{thick\_window\_full}, \Cref{prop:synlower} is
\texttt{syndetic\_window\_nonempty}, and \Cref{thm:lac} is
\texttt{lacunary\_diff\_bounded} with \texttt{lacunary\_no\_recurrence}. All are
in \texttt{Imscribing/Millennium/Erdos/DifferenceSets.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}, depending on
\texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

\end{document}
EOF
