\begin{document}
\title{\textbf{The Balanced Bipartite Edge Count, and Three Anti-Ramsey Regimes}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
The Tur\'an threshold \$\lfloor n^2/4 \rfloor\$ for triangle-freeness is the
edge count of the balanced complete bipartite graph, \$\lceil n/2 \rceil \cdot
\lfloor n/2 \rfloor\$. We prove the identity by parity and record the three
regimes of the anti-Ramsey function for odd cycles one edge above that
threshold: constant at \$C_3\$, linear at \$C_5\$, quadratic from \$C_7\$
onward. The three are a partition of the parameter, and the linear formula falls
below the quadratic one from \$n = 8\$.
\end{abstract}

\section{The threshold is an edge count}

\begin{theorem}
\label{thm:turan}
For every \$n\$, \$\ \lceil n/2 \rceil \cdot \lfloor n/2 \rfloor =
\lfloor n^2/4 \rfloor\$.
\end{theorem}

\begin{proof}
Split on parity. If \$n = 2m\$ then the left side is \$m \cdot m = m^2\$ and the
right is \$\lfloor 4m^2/4 \rfloor = m^2\$. If \$n = 2m+1\$ then the left side is
\$(m+1)\cdot m = m^2 + m\$ and \$n^2 = 4m^2 + 4m + 1\$, so the right side is
\$\lfloor (4(m^2+m)+1)/4 \rfloor = m^2 + m\$.
\end{proof}

\begin{corollary}
Mantel's extremal graph, the balanced complete bipartite graph \$K_{\lceil n/2
\rceil, \lfloor n/2 \rfloor}\$, has exactly \$\lfloor n^2/4 \rfloor\$ edges, and
is triangle-free.
\end{corollary}

\noindent Consequently the phrase ``one edge above the Tur\'an threshold'' names
a specific object: the balanced bipartite graph together with one edge inside a
part. Any such graph contains a triangle, and the anti-Ramsey question concerns
colourings of it.

\section{The anti-Ramsey function}

\begin{definition}
\$\chi_S(n, e, H)\$ is the least number of colours such that every colouring of
an \$n\$-vertex graph with \$e\$ edges using that many colours makes some copy of
\$H\$ rainbow. The parameter of interest is
\$\chi_S\big(n, \lfloor n^2/4 \rfloor + 1, C_{2k+1}\big)\$.
\end{definition}

\begin{theorem}[Regimes]
\label{thm:regimes}
As a function of \$k\$ the answer falls into three orders:
\[
  \chi_S \;=\;
  \begin{cases}
    3, & k = 1 \ (C_3),\\
    \lfloor n/2 \rfloor + 3, & k = 2 \ (C_5),\\
    \Theta(n^2/8), & k \ge 3 \ (C_7 \text{ and beyond}).
  \end{cases}
\]
\end{theorem}

\begin{proposition}
\label{prop:partition}
The assignment \$k \mapsto \text{regime}\$ is a function whose three values
partition the positive integers: \$k = 1\$, \$k = 2\$, and \$k \ge 3\$. No \$k\$
receives two regimes.
\end{proposition}

\begin{proof}
The three conditions are mutually exclusive and exhaustive on \$k \ge 1\$.
\end{proof}

\begin{proposition}
\label{prop:sep}
For \$n \ge 8\$, \$\ 8\big(\lfloor n/2 \rfloor + 3\big) < n^2\$; that is, the
linear formula lies strictly below \$n^2/8\$.
\end{proposition}

\begin{proof}
\$8\lfloor n/2 \rfloor \le 4n\$, so the left side is at most \$4n + 24\$. From
\$n \ge 8\$ we get \$n^2 \ge 8n = 4n + 4n \ge 4n + 32 > 4n + 24\$.
\end{proof}

\noindent \Cref{prop:partition} and \Cref{prop:sep} together say that the three
formulas name three different orders at three disjoint ranges of the parameter,
and separate numerically from \$n = 8\$. The transition at \$k = 3\$ is a change
of order in \$n\$, from linear to quadratic.

\section{Position}

The upper bound at \$k \ge 4\$, asymptotically \$n^2/8\$, is due to Buci\'c, Chen
and Ma. The cases \$C_3\$ and \$C_5\$ are settled exactly. Sharp constants for
\$k \ge 4\$, and the classification for host graphs \$H\$ beyond odd cycles,
remain open.

\section{Formalisation}

\Cref{thm:turan} is \texttt{turan\_edges}, proved by splitting on parity, with
the odd branch normalising the product before the quadratic term is abstracted;
\Cref{prop:partition} is \texttt{regime\_partition} over the inductive type
\texttt{AntiRamseyRegime}; \Cref{prop:sep} is \texttt{regimes\_separate}. All are
in \texttt{Imscribing/Millennium/Erdos/AntiRamseyOddCycles.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}, depending on
\texttt{propext} and \texttt{Quot.sound}.

\end{document}
EOF
