$PRE

\begin{document}
\title{\textbf{The Multicolour Ratio \$R_k(C_{2n+1})/R_k(K_3)\$ Vanishes}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
For fixed \$n \ge 1\$ the ratio of the \$k\$-colour Ramsey numbers of the odd
cycle \$C_{2n+1}\$ and the triangle tends to zero as \$k \to \infty\$. The proof
is a comparison of exponential bases: Bondy--Erd\H{o}s bounds the numerator by
\$(2n+1)2^k\$ and Schur bounds the denominator below by \$3.199^k\$, so the
ratio is at most \$(2n+1)(2/3.199)^k\$, with the dependence on \$n\$ confined to
the constant. Comparisons in which \$n\$ enters the base do not vanish.
\end{abstract}

\section{The bounds}

Let \$R_k(H)\$ denote the least \$N\$ such that every \$k\$-colouring of the edges
of \$K_N\$ contains a monochromatic copy of \$H\$.

\begin{itemize}
\item \textbf{Bondy--Erd\H{o}s.} \$R_k(C_{2n+1}) \le (2n+1)\,2^k\$ for large
\$k\$.
\item \textbf{Schur.} \$R_k(K_3) \ge c^k\$ for some \$c > 3.199\$ and all
sufficiently large \$k\$, from the Schur number lower bounds.
\end{itemize}

\section{The comparison}

\begin{theorem}
\label{thm:bound}
Fix \$n \ge 1\$. For all sufficiently large \$k\$,
\[
  \frac{R_k(C_{2n+1})}{R_k(K_3)} \;\le\; (2n+1)\left(\frac{2}{3.199}\right)^{\!k} .
\]
\end{theorem}

\begin{proof}
Take \$k\$ beyond both thresholds. The denominator is at least \$3.199^k > 0\$,
so the inequality is equivalent to
\[
  R_k(C_{2n+1}) \;\le\; (2n+1)\left(\tfrac{2}{3.199}\right)^{k} R_k(K_3) .
\]
By Bondy--Erd\H{o}s the left side is at most \$(2n+1)2^k\$, and
\[
  (2n+1)\left(\tfrac{2}{3.199}\right)^{k}\!\cdot 3.199^k \;=\; (2n+1)2^k ,
\]
so it suffices that \$3.199^k \le R_k(K_3)\$, which is Schur's bound.
\end{proof}

\begin{corollary}
\label{cor:limit}
For each fixed \$n \ge 1\$,
\$\ R_k(C_{2n+1})/R_k(K_3) \to 0\$ as \$k \to \infty\$.
\end{corollary}

\begin{proof}
\$2/3.199 < 1\$, so \$(2n+1)(2/3.199)^k \to 0\$; the ratio is non-negative and
bounded above by it.
\end{proof}

\section{Where the base must not carry \texorpdfstring{$n$}{n}}

The comparison succeeds because the base \$2/3.199\$ does not depend on \$n\$; the
whole dependence sits in the constant \$2n+1\$, which is irrelevant to a
geometric limit. A bound whose base grows with \$n\$ behaves differently.

\begin{proposition}
\label{prop:base}
For \$n \ge 2\$, \$\ (4n-2)/3.199 > 1\$.
\end{proposition}

\begin{proof}
\$4n - 2 \ge 6 > 3.199\$.
\end{proof}

\noindent Hence a comparison of the form \$C\big((4n-2)/3.199\big)^k\$ diverges
for every \$n \ge 2\$ and bounds nothing. The distinction is not cosmetic: an
upper bound on \$R_k(C_{2n+1})\$ of the shape \$C_n^k \cdot k^{k/n}\$ carries the
cycle length into the base and additionally supplies a superexponential factor,
since \$(k!)^{1/n} = \exp\big((k\log k)/n\big)\$ to leading order, which
outgrows \$c^k\$ for every fixed \$c\$.

\begin{proposition}
\label{prop:super}
For fixed \$n \ge 1\$ and \$c > 1\$, \$\ k\log c < (k \log k)/n\$ as soon as
\$k > c^n\$.
\end{proposition}

\begin{proof}
\$k > c^n\$ gives \$\log k > n \log c\$, and dividing by \$n > 0\$ and
multiplying by \$k > 0\$ preserves the inequality.
\end{proof}

\noindent So against a merely exponential lower bound on \$R_k(K_3)\$, a
factorial upper bound on \$R_k(C_{2n+1})\$ yields a ratio tending to infinity.
\Cref{cor:limit} is available only through the exponential form of the numerator
bound.

\section{Position}

The exact asymptotic of \$R_k(K_3)\$ is open; it is conjectured to grow like
\$k!\$, and the known bounds place it between \$3.199^k\$ and \$O(k! \, e)\$.
\Cref{cor:limit} does not depend on resolving this, since it uses only the lower
bound. Sharp constants for \$R_k(C_{2n+1})\$ are likewise open.

\section{Formalisation}

\Cref{thm:bound} is \texttt{ramsey\_refined\_base\_comparison}, taking the two
cited bounds as hypotheses \texttt{BondyErdosExponential} and
\texttt{SchurLowerBound}; \Cref{cor:limit} rests on
\texttt{refined\_ratio\_tendsto\_zero}; \Cref{prop:base} is
\texttt{base\_exceeds\_one\_from\_two}; \Cref{prop:super} is
\texttt{stirling\_beats\_exponential}. These are in
\texttt{Imscribing/Millennium/ProofModules/RamseyLimit.lean} and
\texttt{Imscribing/Millennium/Erdos/RamseyAsymptotics.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}, depending on
\texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

\end{document}
EOF
