cat > lcm_growth_density.tex <<EOF
$PRE

\begin{document}
\title{\textbf{\$\mathrm{lcm}(1,\dots,n)\$ Exceeds \$n\log(n+1)\$ from \$n=3\$}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
Two consecutive integers are coprime and both divide \$\mathrm{lcm}(1,\dots,n)\$,
so that lcm is at least \$n(n-1)\$. Since \$\log(n+1) < n-1\$ from \$n = 3\$, the
inequality \$\mathrm{lcm}(1,\dots,n) > n\log(n+1)\$ holds at every \$n \ge 3\$,
and the set of \$n\$ satisfying it has density one. The argument uses no
analytic number theory; the elementary quadratic lower bound already outruns the
logarithmic comparison.
\end{abstract}

\section{A quadratic lower bound}

\begin{lemma}
\label{lem:quad}
For \$n \ge 2\$, \$\ n(n-1) \le \mathrm{lcm}(1,\dots,n)\$.
\end{lemma}

\begin{proof}
Both \$n\$ and \$n-1\$ lie in \$\{1,\dots,n\}\$, so both divide
\$L = \mathrm{lcm}(1,\dots,n)\$. Consecutive integers are coprime, so their
product divides \$L\$ as well. As \$L > 0\$, divisibility gives
\$n(n-1) \le L\$.
\end{proof}

\noindent The true growth is \$L = e^{(1+o(1))n}\$ by the prime number theorem
in Chebyshev's form, but nothing below needs it.

\section{A logarithmic upper comparison}

\begin{lemma}
\label{lem:log}
For \$n \ge 3\$, \$\ \log(n+1) < n - 1\$.
\end{lemma}

\begin{proof}
Equivalently \$n + 1 < e^{\,n-1}\$. Since \$x + 1 \le e^x\$ for all real \$x\$,
taking \$x = n-2\$ gives \$n - 1 \le e^{\,n-2}\$, whence
\[
  e^{\,n-1} \;=\; e^{\,n-2} \cdot e \;\ge\; (n-1)\,e \;>\; 2.7(n-1).
\]
For \$n \ge 3\$, \$2.7(n-1) \ge n+1\$ reduces to \$1.7n \ge 3.7\$, which holds.
\end{proof}

\section{The comparison, and the density}

\begin{theorem}
\label{thm:main}
For every \$n \ge 3\$, \$\ \mathrm{lcm}(1,\dots,n) > n\log(n+1)\$.
\end{theorem}

\begin{proof}
By \Cref{lem:log}, \$n \log(n+1) < n(n-1)\$, and by \Cref{lem:quad} the latter is
at most \$\mathrm{lcm}(1,\dots,n)\$.
\end{proof}

\begin{corollary}
The set \$\{\, n : \mathrm{lcm}(1,\dots,n) > n\log(n+1) \,\}\$ contains every
integer from \$3\$ onward, so its density in \$\{1,\dots,N\}\$ tends to \$1\$.
\end{corollary}

\begin{remark}
The inequality also holds at \$n = 2\$, where \$\mathrm{lcm}(1,2) = 2\$ and
\$2\log 3 \approx 2.197\$ --- so it fails there, and \$3\$ is the correct
starting point: \$\mathrm{lcm}(1,2,3) = 6\$ against \$3 \log 4 \approx 4.159\$.
\end{remark}

\section{Position}

The sharp statements about \$L_n = \mathrm{lcm}(1,\dots,n)\$ are analytic:
\$\log L_n = \psi(n)\$ is Chebyshev's second function, \$\psi(n) \sim n\$ is
equivalent to the prime number theorem, and Rosser and Schoenfeld's explicit
bound gives \$\psi(n) \le 1.04\,n\$ for all \$n \ge 1\$. The elementary bound of
\Cref{lem:quad} is far weaker --- quadratic against exponential --- and is
nonetheless already sufficient to settle any comparison of \$L_n\$ against a
function of order \$n \log n\$.

\section{Formalisation}

