$PRE

\begin{document}
\title{\textbf{The GCD of a Binomial Row}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
Write \$h(n) = \gcd\big(\binom{n}{1}, \dots, \binom{n}{n-1}\big)\$. We prove
\$h(n) = p\$ when \$n\$ is a power of the prime \$p\$, and \$h(n) = 1\$
otherwise, and give the digit criterion behind both: a prime \$p\$ divides
\$\binom{n}{i}\$ exactly when the base-\$p\$ addition of \$i\$ and \$n-i\$
carries. In particular \$p \mid \binom{n}{p-1}\$ whenever \$p \mid n\$, since
that index forces a carry --- so divisibility by \$p\$ at a single index is no
obstruction to \$h(n) = 1\$.
\end{abstract}

\section{Kummer's criterion}

\begin{theorem}[Kummer]
\label{thm:kummer}
For a prime \$p\$ and \$0 \le i \le n\$, the exponent of \$p\$ in
\$\binom{n}{i}\$ equals the number of carries when \$i\$ and \$n-i\$ are added in
base \$p\$.
\end{theorem}

\begin{corollary}[Lucas, one step]
\label{cor:lucas}
\$p \nmid \binom{n}{i}\$ if and only if every base-\$p\$ digit of \$i\$ is at
most the corresponding digit of \$n\$.
\end{corollary}

\noindent Both criteria are about digits, and every statement below is a
statement about digits.

\section{Prime powers}

\begin{theorem}
\label{thm:pp}
If \$n = p^m\$ with \$m \ge 1\$ then \$p \mid \binom{n}{i}\$ for every
\$1 \le i \le n-1\$, so \$p \mid h(n)\$.
\end{theorem}

\begin{proof}
In base \$p\$ the number \$n = p^m\$ is a single \$1\$ followed by \$m\$ zeros.
For \$1 \le i \le n-1\$ the numeral of \$i\$ is not all zeros below position
\$m\$, so some digit of \$i\$ exceeds the corresponding digit \$0\$ of \$n\$. By
\Cref{cor:lucas}, \$p \mid \binom{n}{i}\$.
\end{proof}

\begin{theorem}
\label{thm:ppexact}
For \$n = p^m\$, \$h(n) = p\$ exactly.
\end{theorem}

\begin{proof}
\Cref{thm:pp} gives \$p \mid h(n)\$. For the reverse, \$\binom{p^m}{1} = p^m\$
and \$\binom{p^m}{p^{m-1}}\$ have \$p\$-adic valuations \$m\$ and \$1\$
respectively --- the latter because adding \$p^{m-1}\$ to \$p^m - p^{m-1}\$ in
base \$p\$ produces exactly one carry --- so the gcd has \$p\$-adic valuation
\$1\$. No other prime divides \$\binom{p^m}{1} = p^m\$.
\end{proof}

\section{The obstruction at composite \$n\$}

\begin{theorem}
\label{thm:carry}
Let \$p\$ be a prime with \$p \mid n\$ and \$p \le n\$. Then
\$p \mid \binom{n}{p-1}\$.
\end{theorem}

\begin{proof}
Since \$p \mid n\$, the last base-\$p\$ digit of \$n\$ is \$0\$. The last digit of
\$i = p-1\$ is \$p-1 > 0\$. By \Cref{cor:lucas} the digit condition fails at
position zero, so \$p\$ divides the coefficient. Equivalently, adding \$p-1\$ to
\$n - (p-1)\$ in base \$p\$ carries out of the units place.
\end{proof}

\noindent \Cref{thm:carry} shows that finding one index at which \$p\$ divides
the coefficient says nothing: for every prime factor \$p\$ of \$n\$ there is
always such an index. The gcd is governed by whether a single prime divides the
\emph{whole} row.

\begin{theorem}
\label{thm:one}
If \$n\$ has at least two distinct prime factors then \$h(n) = 1\$.
\end{theorem}

\begin{proof}
Let \$p \neq q\$ divide \$n\$, and write \$n\$ in base \$p\$. Since \$n\$ is not a
power of \$p\$, its base-\$p\$ numeral has a non-zero digit \$d\$ in some position
\$j\$ below the leading one. Take \$i = d\,p^j\$: every digit of \$i\$ is at most
the corresponding digit of \$n\$, so by \Cref{cor:lucas} \$p \nmid \binom{n}{i}\$
while \$1 \le i \le n-1\$. Hence \$p \nmid h(n)\$. The same applies to every
prime dividing \$n\$, and a prime not dividing \$n\$ does not divide
\$\binom{n}{1} = n\$. So \$h(n)\$ has no prime factor.
\end{proof}

\begin{corollary}
\[
  h(n) \;=\;
  \begin{cases}
    p, & n = p^m,\ m \ge 1,\\
    1, & \text{otherwise.}
  \end{cases}
\]
In particular \$h(n) \to \infty\$ along the primes and along prime powers with
bounded base, and \$h(n) = 1\$ on a set of density one.
\end{corollary}

\section{Position}

The behaviour along the full sequence is therefore settled: \$h\$ is unbounded on
a subsequence and equal to \$1\$ almost everywhere, so it has no limit. The
related question of Erd\H{o}s and Graham, whether \$\gcd\big(\binom{n}{i},
\binom{n}{j}\big) > 1\$ for all large \$n\$ and suitable \$i \neq j\$, is not
settled by the row gcd and remains open.

\section{Formalisation}

\Cref{thm:pp} is \texttt{prime\_le\_gcd\_choose}, resting on Mathlib's
\texttt{Nat.Prime.dvd\_choose\_pow}; \Cref{cor:lucas} in the form used is
\texttt{dvd\_choose\_of\_units\_digit\_exceeds}; \Cref{thm:carry} is
\texttt{dvd\_choose\_pred\_of\_dvd}; and the digit descent is
\texttt{choose\_modEq\_of\_dvd\_dvd}. All are in
\texttt{Imscribing/Millennium/Erdos/BinomialGCD.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}, depending on
\texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

\end{document}
EOF
