cat > sdr_window.tex <<EOF
$PRE

\begin{document}
\title{\textbf{Windows Carrying a System of Distinct Multiples}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
Let \$f(n,m)\$ be the least \$\ell\$ such that the interval \$(m, m+\ell]\$
contains distinct integers \$a_1,\dots,a_n\$ with \$i \mid a_i\$ for each \$i\$.
Minimised over the window position the answer is exactly \$n\$, attained just
above \$\mathrm{lcm}(1,\dots,n)\$. At the window starting at \$n\$ the values are
\$f(n,n) = 1,2,3,5,5,8,8,10,12\$ for \$n \le 9\$, computed by a backtracking
matcher; the first departure from \$n\$ occurs at \$n = 4\$, where the window
\$(4,8]\$ has only two even numbers and three indices requiring one.
\end{abstract}

\section{Two quantities, not one}

\begin{definition}
\$f(n,m)\$ is the least \$\ell \ge 0\$ such that there are distinct
\$a_1,\dots,a_n \in (m, m+\ell]\$ with \$i \mid a_i\$ for every
\$1 \le i \le n\$.
\end{definition}

\noindent The interval length is not the only variable: where the window sits
matters, and the two natural specialisations behave differently. Minimising over
\$m\$ is trivial; fixing \$m = n\$ is not.

\section{The minimising window}

\begin{theorem}
\label{thm:min}
\$\min_m f(n,m) = n\$.
\end{theorem}

\begin{proof}
The lower bound is immediate: \$n\$ distinct integers require \$\ell \ge n\$.

For the upper bound take \$m = \mathrm{lcm}(1,\dots,n)\$ and
\$\ell = n\$. Each \$i \le n\$ divides \$m\$, hence divides \$m + i\$, and the
\$n\$ values \$m+1, \dots, m+n\$ are distinct and lie in \$(m, m+n]\$. Assigning
\$a_i = m + i\$ satisfies \$i \mid a_i\$.
\end{proof}

\noindent So the minimising reading of the problem is settled by one line, and
the interesting quantities are \$f(n,n)\$ and \$\max_m f(n,m)\$.

\section{The window at \$n\$}

The existence of the required system is a bipartite matching question: indices
on one side, integers of the window on the other, an edge when the index divides
the integer. Hall's condition governs solvability, and a backtracking walk over
the indices decides it constructively.

\begin{theorem}
\label{thm:values}
For \$n = 1,\dots,9\$,
\[
  f(n,n) \;=\; 1,\;2,\;3,\;5,\;5,\;8,\;8,\;10,\;12 .
\]
\end{theorem}

\begin{proof}
For each \$\ell\$ in turn, run the matcher: assign to index \$1\$ any unused
multiple of \$1\$ in the window, then to index \$2\$ any unused multiple of
\$2\$, and so on, backtracking on failure. The walk succeeds exactly when a
system exists, so the least successful \$\ell\$ is \$f(n,n)\$.
\end{proof}

\begin{proposition}
\label{prop:four}
\$f(4,4) = 5\$; in particular \$f(n,n) > n\$ first occurs at \$n = 4\$.
\end{proposition}

\begin{proof}
The window \$(4,8] = \{5,6,7,8\}\$ contains exactly two even numbers, \$6\$ and
\$8\$. Index \$4\$ requires a multiple of \$4\$, which forces \$a_4 = 8\$; index
\$2\$ then requires an even number, forcing \$a_2 = 6\$; index \$3\$ requires a
multiple of \$3\$, and \$6\$ is the only one in the window and is taken. So
\$\ell = 4\$ fails. At \$\ell = 5\$ the window \$\{5,6,7,8,9\}\$ admits
\$a_4 = 8\$, \$a_2 = 6\$, \$a_3 = 9\$, \$a_1 = 5\$.
\end{proof}

\section{Position}

Erd\H{o}s and Pomerance bracket the window at \$n\$ by
\[
  \Big(\tfrac{2}{\sqrt e} + o(1)\Big)\, n \sqrt{\tfrac{\log n}{\log\log n}}
  \;<\; f(n,n) \;<\; \big(2 + o(1)\big)\, n \sqrt{\log n},
\]
the two ends differing by a factor \$\sqrt{\log\log n}\$; the order of
\$f(n,n)\$ is not known. Separately, van Doorn has shown
\$\max_m f(n,m) - f(n,n) > 0.36\, n \log n / \log\log n\$, so the worst window is
genuinely worse than the window at \$n\$ --- the question Erd\H{o}s attached a
prize to. The two quantities are different, and a bound on one is not a bound on
the other.

\section{Formalisation}

\Cref{thm:min} is \texttt{exists\_distinct\_multiples\_window} in the section
\texttt{SDRWindow}; the matcher is \texttt{matchFrom} with \texttt{hasSDR} and
\texttt{fnn}, and \Cref{thm:values} is \texttt{fnn\_table}, with
\Cref{prop:four} split as \texttt{four\_window\_fails} and
\texttt{four\_window\_works}. All are in
\texttt{Imscribing/Millennium/Erdos/PomeranceSDR.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}. The table
uses compiled evaluation and carries \texttt{ofReduceBool}; \Cref{thm:min}
depends on \texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

\end{document}
EOF
