$PRE

\begin{document}
\title{\textbf{Two Hypotheses for Arithmetic Progressions}}
\author{C.\ L.\ Mills (Lando\,\$\otimes\$\,\$\odot\$-operator)}
\date{11 August 2026}
\maketitle

\begin{abstract}
Szemer\'edi's theorem takes positive upper density as its hypothesis; the
Erd\H{o}s--Tur\'an conjecture takes \$\sum 1/a_n = \infty\$. The second is
strictly weaker: positive density implies divergence, and the primes have
divergent reciprocal sum with density zero. For three-term progressions both
hypotheses are settled --- Roth's theorem for density, Bloom--Sisask for the
reciprocal sum --- and Behrend's construction shows Roth's decay cannot be
improved to a power saving. For \$k \ge 4\$ the conjecture is open.
\end{abstract}

\section{The two hypotheses}

Let \$A = \{a_1 < a_2 < \cdots\} \subseteq \mathbb{N}\$.

\begin{itemize}
\item \textbf{(D)} \$\limsup_N |A \cap [0,N)| / N > 0\$.
\item \textbf{(R)} \$\sum_n 1/a_n = \infty\$.
\end{itemize}

\begin{proposition}
\label{prop:implies}
(D) implies (R).
\end{proposition}

\begin{proof}
It suffices to see the finite form: if \$A \cap [0,N)\$ has at least
\$\varepsilon N\$ elements then those elements contribute at least
\$\varepsilon N \cdot \tfrac1N = \varepsilon\$ to \$\sum_{a \in A, a < N} 1/a\$,
since each is at most \$N\$. Applying this along a sequence of scales
\$N_1 < N_2 < \cdots\$ on which the density stays above \$\varepsilon\$ and
which grows fast enough that the ranges are disjoint gives divergence.
\end{proof}

\begin{proposition}
\label{prop:strict}
The implication is strict: the primes satisfy (R) and not (D).
\end{proposition}

\begin{proof}
\$\sum_p 1/p\$ diverges, and \$\pi(N)/N \to 0\$.
\end{proof}

\noindent So a theorem with hypothesis (D) does not settle a conjecture with
hypothesis (R). Szemer\'edi's theorem and the Erd\H{o}s--Tur\'an conjecture are
different statements, and the latter is the stronger.

\section{Three terms, under density}

\begin{theorem}[Roth]
\label{thm:roth}
For every \$\varepsilon > 0\$ there is \$N_0(\varepsilon)\$ such that any
\$A \subseteq [0,N)\$ with \$|A| \ge \varepsilon N\$ and \$N \ge N_0\$ contains
three distinct elements in arithmetic progression.
\end{theorem}

\begin{corollary}
\label{cor:density}
Writing \$r_3(N)\$ for the largest progression-free subset of \$[0,N)\$,
\$\ r_3(N) = o(N)\$.
\end{corollary}

\begin{theorem}[Behrend]
\label{thm:behrend}
\$\ r_3(N) \;\ge\; N \exp\!\big(-4\sqrt{\log N}\,\big)\$.
\end{theorem}

\begin{corollary}
The decay in \Cref{cor:density} is slower than any power of \$N\$: there is no
\$\delta > 0\$ with \$r_3(N) = O(N^{1-\delta})\$.
\end{corollary}

\begin{proof}
\$\exp(-4\sqrt{\log N})\$ exceeds \$N^{-\delta} = \exp(-\delta \log N)\$ for
large \$N\$, since \$4\sqrt{\log N} < \delta \log N\$ once
\$\log N > (4/\delta)^2\$.
\end{proof}

\noindent Behrend's construction places points on a sphere in a high-dimensional
grid, where convexity forbids a midpoint; the dimension is tuned against the
side length, which is where \$\sqrt{\log N}\$ enters.

\section{Three terms, under divergence}

The case \$k = 3\$ of the Erd\H{o}s--Tur\'an conjecture --- that (R) forces a
three-term progression --- is a theorem of Bloom and Sisask, whose bound
\$r_3(N) \ll N/(\log N)^{1+c}\$ crosses the threshold at which the reciprocal
sum of a progression-free set must converge. No case \$k \ge 4\$ is known.

\section{Position}

\begin{center}
\begin{tabularx}{0.92\textwidth}{@{}lXX@{}}
\toprule
& \textbf{hypothesis (D)} & \textbf{hypothesis (R)} \\
\midrule
\$k = 3\$ & Roth & Bloom--Sisask \\
\$k \ge 4\$ & Szemer\'edi & open \\
\bottomrule
\end{tabularx}
\end{center}

\noindent Furstenberg's ergodic proof and Gowers's quantitative proof both
establish the (D) column; Green and Tao established progressions in the primes,
which is a statement about a specific set of density zero and not about
hypothesis (R) in general.

\section{Formalisation}

\Cref{thm:roth} is \texttt{dense\_has\_3ap}, \Cref{cor:density} is
\texttt{roth\_density\_tendsto\_zero} and \Cref{thm:behrend} is
\texttt{behrend\_lower\_bound}, each instantiated from Mathlib;
\Cref{prop:strict} rests on \texttt{primes\_reciprocal\_diverges}, and the
finite form of \Cref{prop:implies} is \texttt{density\_gives\_reciprocal\_mass}.
All are in \texttt{Imscribing/Millennium/Erdos/ErdosTuranAP.lean} on the branch
\texttt{crystalline/erdos-audit-2026-08-11} of \texttt{p4rakernel}, depending on
\texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

\end{document}
EOF
