build('erdos_straus_classes', 'Erd\\H{o}s--Straus Outside One Congruence Class', r"""
\begin{abstract}
The Erd\H{o}s--Straus conjecture asserts that for every integer $n \ge 2$ the
fraction $4/n$ is a sum of three unit fractions. It is open. What is settled is
every congruence class but one.

We give four parametric families, each verified as a polynomial identity after
clearing denominators, covering $n$ even, $n \equiv 3 \pmod 4$,
$n \equiv 2 \pmod 4$ and $n \equiv 9 \pmod{12}$. Together they dispose of every
$n \ge 2$ except those with $n \equiv 1 \pmod 4$ and $3 \nmid n$, and we show
that the conjecture is equivalent to that single class. The gap is thereby
located rather than estimated: it is not a residue left over by the method but
the place where the difficulty of the problem is concentrated.
\end{abstract}

\section{Statement}

\begin{definition}
A \emph{solution at $n$} is a triple of positive integers $(x,y,z)$ with
\[
  \boxed{\; 4xyz \;=\; n\,(yz + xz + xy) \;}
\]
which is the equation $4/n = 1/x + 1/y + 1/z$ cleared of denominators.
\end{definition}

The conjecture asserts a solution at every $n \ge 2$.

\section{Four families}

\begin{theorem}[$n$ even]
\label{thm:even}
For $n = 2m$ with $m \ge 1$, the triple $\big(m,\ m+1,\ m(m+1)\big)$ is a
solution.
\end{theorem}

\begin{proof}
Directly,
\[
  \frac1m + \frac1{m+1} + \frac1{m(m+1)}
   \;=\; \frac{(m+1) + m + 1}{m(m+1)}
   \;=\; \frac{2m+2}{m(m+1)}
   \;=\; \frac2m
   \;=\; \frac{4}{2m}.
\]
Cleared of denominators this is a polynomial identity in $m$.
\end{proof}

\begin{theorem}[$n \equiv 3 \pmod 4$]
\label{thm:three}
For $n = 4k+3$, put $M = n(k+1)$. The triple
$\big(k+1,\ M+1,\ M(M+1)\big)$ is a solution.
\end{theorem}

\begin{proof}
Since $4(k+1) - (4k+3) = 1$,
\[
  \frac4n - \frac1{k+1}
   \;=\; \frac{4(k+1) - n}{n(k+1)}
   \;=\; \frac{1}{n(k+1)}
   \;=\; \frac1M .
\]
Now split the remaining tail by the identity
$\tfrac1M = \tfrac1{M+1} + \tfrac1{M(M+1)}$.
\end{proof}

\begin{theorem}[$n \equiv 2 \pmod 4$]
\label{thm:two}
For $n = 4k+2$, the triple
$\big(k+1,\ (2k+1)(2k+2),\ (2k+1)(2k+2)\big)$ is a solution.
\end{theorem}

\begin{proof}
Here $n = 2(2k+1)$, so $4/n = 2/(2k+1)$, and
\[
  \frac{2}{2k+1} - \frac1{k+1}
   \;=\; \frac{2(k+1) - (2k+1)}{(2k+1)(k+1)}
   \;=\; \frac{1}{(2k+1)(k+1)} .
\]
Halving that tail into two equal parts produces the repeated denominator
$(2k+1)(2k+2)$.
\end{proof}

\begin{theorem}[$n \equiv 9 \pmod{12}$]
\label{thm:twelve}
For $n = 12k+9$, the triple $\big(3k+3,\ 2n(k+1),\ 2n(k+1)\big)$ is a solution.
\end{theorem}

\begin{proof}
Since $4(3k+3) - n = 12k + 12 - (12k+9) = 3$,
\[
  \frac4n - \frac1{3k+3}
   \;=\; \frac{3}{n(3k+3)}
   \;=\; \frac{3}{3n(k+1)}
   \;=\; \frac{1}{n(k+1)} ,
\]
and halving that tail gives the two denominators $2n(k+1)$. At $k = 0$ this reads
\[
  \frac49 \;=\; \frac13 + \frac1{18} + \frac1{18} .
\]
\end{proof}

\section{What the families cover}

\begin{theorem}
\label{thm:cover}
Every $n \ge 2$ with $\neg\,\big(n \equiv 1 \bmod 4 \ \wedge\ 3 \nmid n\big)$
has a solution.
\end{theorem}

\begin{proof}
Split on $n \bmod 4$. For $n \equiv 0$ and $n \equiv 2$ apply \Cref{thm:even}
and \Cref{thm:two}. For $n \equiv 3$ apply \Cref{thm:three}. For $n \equiv 1$
the hypothesis forces $3 \mid n$, hence $n \equiv 9 \pmod{12}$, and
\Cref{thm:twelve} applies.
\end{proof}

\section{The gap is exactly one class}

\begin{theorem}
\label{thm:equiv}
The Erd\H{o}s--Straus conjecture is equivalent to the assertion that every
$n \ge 2$ with $n \equiv 1 \pmod 4$ and $3 \nmid n$ has a solution.
\end{theorem}

\begin{proof}
One direction is a restriction of the conjecture to a subclass. For the other,
let $n \ge 2$. Either it lies in the named class, and the assumption applies, or
it does not, and \Cref{thm:cover} applies.
\end{proof}

The remaining class is not a residue left behind by a weak method. It is where
the problem lives. Modular covering arguments dispose of $n$ in many residue
classes to larger moduli, but the primes $n \equiv 1 \pmod{24}$ resist all of
those currently known, and it is a theorem of Elsholtz and Tao that the number of
solutions, averaged over $n$, is governed by exactly this class.

\section{Verification}

The four families are formalised in \Lean{} against Mathlib, each discharged by
ring normalisation of the cleared equation, together with the covering theorem
and the equivalence; all depend on \texttt{propext}, \texttt{Classical.choice}
and \texttt{Quot.sound}.

\begin{thebibliography}{9}
\bibitem{Mordell1969} L.~J.~Mordell, \emph{Diophantine Equations}, Academic
Press, 1969, ch.~30.

\bibitem{Vaughan1970} R.~C.~Vaughan, \emph{On a problem of Erd\H{o}s, Straus and
Schinzel}, Mathematika \textbf{17} (1970), 193--198.

\bibitem{ElsholtzTao} C.~Elsholtz and T.~Tao, \emph{Counting the number of
solutions to the Erd\H{o}s--Straus equation on unit fractions}, J.\ Aust.\ Math.\
Soc.\ \textbf{94} (2013), 50--105.

\bibitem{Guy} R.~K.~Guy, \emph{Unsolved Problems in Number Theory}, 3rd ed.,
Springer, 2004, problem D11.
\end{thebibliography}

\end{document}
""")

build('kac_interval_prime_powers', 'An Interval on Which $\\omega(n) > \\log\\log n$ Contains No Prime Power', r"""
\begin{abstract}
Let $I \subseteq [x, 2x]$ be an interval on which the inequality
$\omega(n) > \log\log n$ holds at every point, where $\omega$ counts distinct
prime factors. We show that $I$ contains no prime power beyond $15$.

The reason is a collision between two very slowly moving quantities. A prime
power has $\omega = 1$ exactly, while $\log\log n$ passes $1$ at
$e^e \approx 15.154$ and never returns. Past that point no prime power can
satisfy the inequality, so an interval on which it holds everywhere must avoid
the primes and their powers entirely, and its length is bounded by the largest
prime-power gap into which it can be placed. This converts a question about
additive functions into a question about prime gaps.
\end{abstract}

\section{The threshold}

\begin{lemma}
\label{lem:sixteen}
$\log\log 16 > 1$.
\end{lemma}

\begin{proof}
We have
\[
  \log 16 \;=\; 4 \log 2 \;>\; 4 \times 0.6931471803 \;=\; 2.7725887212 ,
\]
while $e < 2.7182818286$. Hence $\log 16 > e$, and applying the logarithm, which
is increasing, gives $\log\log 16 > \log e = 1$.
\end{proof}

\begin{lemma}
\label{lem:mono}
For real $n \ge 16$ we have $\log\log n \ge \log\log 16$.
\end{lemma}

\begin{proof}
The logarithm is increasing and $\log 16 > 0$, so $\log n \ge \log 16 > 0$, and a
second application preserves the inequality.
\end{proof}

\section{Prime powers are excluded}

\begin{theorem}
\label{thm:excl}
Let $n \ge 16$ be a prime power. Then $\omega(n) \le \log\log n$; that is, $n$
fails the inequality $\omega(n) > \log\log n$.
\end{theorem}

\begin{proof}
A prime power has exactly one distinct prime factor, so $\omega(n) = 1$. By
\Cref{lem:mono} and \Cref{lem:sixteen},
\[
  \log\log n \;\ge\; \log\log 16 \;>\; 1 \;=\; \omega(n).
\]
\end{proof}

\begin{corollary}
\label{cor:interval}
If $\omega(n) > \log\log n$ for every $n \in I$ and $\min I \ge 16$, then
\[
  \boxed{\; I \text{ contains no prime power, and in particular no prime.} \;}
\]
\end{corollary}

\section{The consequence for length}

Write $G(x)$ for the largest gap between consecutive prime powers in $[x, 2x]$.
By \Cref{cor:interval} the interval $I$ lies strictly between two consecutive
prime powers, so
\[
  |I| \;\le\; G(x) - 1 .
\]
Prime powers other than primes are sparse --- there are $O(\sqrt{x})$ of them
below $x$ --- so $G(x)$ agrees with the maximal prime gap in $[x,2x]$ up to the
rare interference of a square or higher power, and the bound is in substance a
prime-gap bound.

This locates the difficulty precisely. Unconditionally, maximal prime gaps in
$[x,2x]$ are known to be at least of order
\[
  \log x \cdot \frac{\log\log x \; \log\log\log\log x}{\log\log\log x},
\]
and are not known to be $O(\log^2 x)$; under the Riemann hypothesis they are
$O(\sqrt{x} \log x)$, which is far too weak to be useful at this scale.
Consequently any lower bound on $|I|$ exceeding the known prime-gap lower bounds
requires a construction placing $I$ inside a long prime-free stretch, and any
upper bound on $|I|$ beyond $G(x) - 1$ requires more than \Cref{cor:interval}.

\section{Position}

The Erd\H{o}s question asks for the size of the largest such $I$ in $[x,2x]$. The
Chinese remainder theorem supplies a lower bound by forcing each $n+j$ across a
block to carry many small prime factors simultaneously. Erd\H{o}s conjectured
\[
  |I| \;\ge\; (\log x)^k \qquad \text{for every fixed } k,
\]
which remains open. Writing $L = \log x$, the ratio between the CRT bound
$L / (\log L)^2$ and the conjecture $L^k$ is $L^{k-1} (\log L)^2$: polynomial in
$L$, and therefore exponential in $\log L$ rather than in $L$.

\section{Verification}

The threshold, its monotone extension and the exclusion are formalised in
\Lean{} against Mathlib, taking the numeric bounds on $\log 2$ and $e$ from the
library; all depend on \texttt{propext}, \texttt{Classical.choice} and
\texttt{Quot.sound}.

\begin{thebibliography}{9}
\bibitem{ErdosKac1940} P.~Erd\H{o}s and M.~Kac, \emph{The Gaussian law of errors
in the theory of additive number theoretic functions}, Amer.\ J.\ Math.\
\textbf{62} (1940), 738--742.

\bibitem{Rankin1938} R.~A.~Rankin, \emph{The difference between consecutive
prime numbers}, J.\ London Math.\ Soc.\ \textbf{13} (1938), 242--247.

\bibitem{FGKMT} K.~Ford, B.~Green, S.~Konyagin, J.~Maynard and T.~Tao,
\emph{Long gaps between primes}, J.\ Amer.\ Math.\ Soc.\ \textbf{31} (2018),
65--105.

\bibitem{ErdosGraham1980} P.~Erd\H{o}s and R.~L.~Graham, \emph{Old and New
Problems and Results in Combinatorial Number Theory}, Monographies de
L'Enseignement Math\'ematique 28, Gen\`eve, 1980.
\end{thebibliography}

\end{document}
""")
PYEOF

