build('alternating_prime_series', 'The Terms of $\\sum (-1)^n n/p_n$ Are Not Eventually Monotone', r"""
\begin{abstract}
Let $a_n = n/p_n$, where $p_n$ is the $n$-th prime. The alternating series test
requires two things of the magnitudes: that they tend to zero, and that they
eventually decrease. The first holds. We prove that the second fails on every
tail.

The criterion is exact and entirely algebraic: $a_n < a_{n+1}$ precisely when
$p_n > n\,g_n$, where $g_n = p_{n+1} - p_n$ is the gap. Clearing denominators
turns the comparison of two ratios into a comparison of two products, and the gap
appears by substitution. Bounded gaps therefore force a rise as soon as $p_n$
passes $n B$, and since $p_n/n \to \infty$ every fixed bound $B$ eventually falls
below that line. Consequently there is no index beyond which $(a_n)$ decreases,
and the convergence of $\sum (-1)^n a_n$, if it holds, cannot come from the
alternating series test.
\end{abstract}

\section{An exact criterion for a rise}

\begin{theorem}[Rise criterion]
\label{thm:rise}
Let $(p_n)$ be positive with $p_n < p_{n+1}$ and set $a_n = n/p_n$. Then
\[
  \boxed{\; a_n < a_{n+1}
   \quad\Longleftrightarrow\quad
   n\,(p_{n+1} - p_n) \;<\; p_n . \;}
\]
\end{theorem}

\begin{proof}
Both denominators are positive, so
\[
  \frac{n}{p_n} < \frac{n+1}{p_{n+1}}
  \quad\Longleftrightarrow\quad
  n\,p_{n+1} < (n+1)\,p_n .
\]
Substituting $p_{n+1} = p_n + g_n$ turns the left side into $n p_n + n g_n$ and
the right into $n p_n + p_n$; cancelling $n p_n$ leaves $n g_n < p_n$.
\end{proof}

No analysis enters. The whole content is that comparing two ratios is comparing
two products.

\begin{corollary}
\label{cor:small}
If $g_n \le B$ and $nB < p_n$ then $a_n < a_{n+1}$.
\end{corollary}

\section{No monotone tail}

\begin{theorem}
\label{thm:nomono}
Suppose the gaps are bounded infinitely often --- there is $B$ such that for every
$N$ some $n \ge N$ has $g_n \le B$ --- and that $p_n/n \to \infty$. Then there is
no $N$ with $a_{n+1} \le a_n$ for all $n \ge N$.
\end{theorem}

\begin{proof}
Fix such an $N$ for contradiction. Superlinearity applied at the constant $B$
gives $M$ with $nB < p_n$ for all $n \ge M$. Bounded gaps applied at
$\max(N,M)$ give some $n \ge \max(N,M)$ with $g_n \le B$. By \Cref{cor:small},
$a_n < a_{n+1}$, contradicting the assumed decrease at that $n$.
\end{proof}

Both hypotheses hold for the primes. The first is the bounded gaps theorem of
Zhang, as sharpened by Maynard and by the Polymath project, which gives
$g_n \le 246$ infinitely often. The second is the prime number theorem, under
which $p_n \sim n \log n$ and so $p_n/n \to \infty$.

\section{Twin primes, and the smallest instance}

\begin{corollary}
\label{cor:twin}
At any index $n$ with $g_n = 2$ and $p_n > 2n$, the term rises.
\end{corollary}

\begin{proof}
\Cref{cor:small} with $B = 2$.
\end{proof}

Indexing the primes from $p_1 = 2$, the smallest such index is $n = 13$, where
$p_{13} = 41$ and $p_{14} = 43$, and $41 > 26$:
\[
  a_{13} = \frac{13}{41} \approx 0.3171
  \;<\;
  \frac{14}{43} \approx 0.3256 = a_{14} .
\]

\section{Consequence for the series}

The alternating series test requires the magnitudes to tend to zero and to be
eventually monotone decreasing. The first hypothesis holds, since
$p_n \sim n \log n$ gives $a_n \to 0$. \Cref{thm:nomono} denies the second on
every tail.

Hence the convergence of $\sum (-1)^n n/p_n$, if it holds, must come from
cancellation between paired terms, which is a statement about the sequence of
gaps rather than about the magnitudes alone. Terms tending to zero are not
sufficient for a series whose signs are imposed externally rather than arising
from monotone decrease.

\section{Verification}

The criterion and the failure of monotonicity are formalised in \Lean{} against
Mathlib. The two analytic inputs are carried as explicit hypotheses rather than
assumed, and every result depends on \texttt{propext}, \texttt{Classical.choice}
and \texttt{Quot.sound}.

