\bibitem{MontgomeryVaughan} H.~L.~Montgomery and R.~C.~Vaughan, \emph{On the
Erd\H{o}s--Fuchs theorem}, in A Tribute to Paul Erd\H{o}s, Cambridge Univ.\
Press, 1990, 331--338.

\bibitem{Sarkozy1980} A.~S\'ark\"ozy, \emph{On a theorem of Erd\H{o}s and Fuchs},
