build('syndetic_difference_sets', 'Thick Sets, Syndetic Sets, and a Lacunary Difference Set', r"""
\begin{abstract}
Bounded gaps and arbitrarily long runs are complementary notions, and the
complementarity is exact: a set of integers is thick precisely when its
complement is not syndetic. We prove that duality, and then two facts that are
easy to state backwards.

A thick set does not have upper Banach density zero; it has density one, because
it fills a window of every length completely. A syndetic set has positive
\emph{lower} Banach density, since it meets every window of its gap length. These
are not two strengths of one notion: syndeticity bounds every window from below,
while thickness fills one window per length.

At the opposite extreme sits the lacunary set $\{2^n\}$, for which every non-zero
difference pins both exponents, so no non-zero difference recurs and the
difference set is $\{0\}$.
\end{abstract}

\section{Two notions}

\begin{definition}
A set $S \subseteq \mathbb{Z}$ is \emph{syndetic} when there is $N \ge 1$ such
that every window $\{x, x+1, \dots, x+N-1\}$ meets $S$. It is \emph{thick} when
for every $N$ some window of length $N$ is contained in $S$.
\end{definition}

\begin{theorem}[Duality]
\label{thm:dual}
\[
  \boxed{\; S \text{ is thick}
   \quad\Longleftrightarrow\quad
   \mathbb{Z} \setminus S \text{ is not syndetic.} \;}
\]
\end{theorem}

\begin{proof}
Suppose $S$ is thick and the complement is syndetic with constant $N$. Thickness
gives a window of length $N$ inside $S$, and syndeticity gives a point of the
complement inside that window. That point lies in both $S$ and its complement.

Conversely suppose the complement is not syndetic. For $N = 0$ thickness is
vacuous. For $N \ge 1$, were no window of length $N$ contained in $S$, every
window of length $N$ would meet the complement, making it syndetic with constant
$N$.
\end{proof}

\section{Density of a thick set}

\begin{definition}
Write $\operatorname{cnt}_S(x,N) = \#\{0 \le i < N : x + i \in S\}$. Say $S$ has
\emph{upper Banach density zero} when for every $c > 0$ there is $N \ge 1$ with
$\operatorname{cnt}_S(x,N) < cN$ for every $x$.
\end{definition}

\begin{theorem}
\label{thm:thickdense}
A thick set does not have upper Banach density zero.
\end{theorem}

\begin{proof}
Apply the definition at $c = 1$ to obtain $N \ge 1$ with
$\operatorname{cnt}_S(x,N) < N$ for every $x$. Thickness supplies an $x$ with the
whole window inside $S$, so $\operatorname{cnt}_S(x,N) = N$.
\end{proof}

In fact the supremum of window densities is $1$: a thick set fills a window of
every length completely. Thickness is a density-one phenomenon, not a
density-zero one.

\begin{proposition}
\label{prop:synlower}
A syndetic set with constant $N$ satisfies $\operatorname{cnt}_S(x,N) \ge 1$ for
every $x$, so its lower Banach density is at least $1/N$.
\end{proposition}

\begin{proof}
Immediate from the definition: the window from $x$ of length $N$ meets $S$.
\end{proof}

\section{Recurrence, and the lacunary extreme}

\begin{definition}
$D(A) = \{ d : |A \cap (A - d)| = \infty \}$, the set of differences occurring
infinitely often in $A$.
\end{definition}

\begin{theorem}
\label{thm:lac}
Let $A = \{2^n : n \ge 0\}$ and let $d > 0$. If $2^a - 2^b = d$ with $b < a$ then
\[
  2^b \le d \qquad\text{and}\qquad 2^a \le 2d .
\]
Consequently each non-zero $d$ is realised by only finitely many pairs, and
\[
  \boxed{\; D\big(\{2^n\}\big) = \{0\}. \;}
\]
\end{theorem}

\begin{proof}
Factor $d = 2^b(2^{a-b} - 1)$. Since $a > b$ the cofactor is at least $1$, so
$2^b \le d$; and then $2^a = d + 2^b \le 2d$. Both exponents are bounded in terms
of $d$, leaving finitely many pairs. As $0 \in D(A)$ trivially and no other $d$
recurs, $D(A) = \{0\}$.
\end{proof}

\begin{corollary}
$D(A)$ is not syndetic for $A = \{2^n\}$: a single point has unbounded gaps.
\end{corollary}

\section{Position}

For $A$ of positive upper Banach density, the Furstenberg correspondence
principle transports $A$ to a measure-preserving system in which Poincar\'e
recurrence applies, and $D(A)$ is syndetic; indeed it contains a Bohr$_0$ set.
The converse fails, so positive density is sufficient and not necessary.

A counterexample to the converse must be a set of density zero whose difference
set nonetheless has bounded gaps. By \Cref{thm:thickdense} a thick set is not one,
since thickness supplies density one rather than zero. A complete
characterisation of the sets $A$ for which $D(A)$ is syndetic remains open.

\section{Verification}

The duality, the density of a thick set, the lower bound for a syndetic set and
the lacunary computation are formalised in \Lean{} against Mathlib, all depending
on \texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

