build('mantel_anti_ramsey', 'The Balanced Bipartite Edge Count, and Three Anti-Ramsey Regimes', r"""
\begin{abstract}
The Tur\'an threshold for triangle-freeness, $\lfloor n^2/4 \rfloor$, is not
merely a bound: it is the edge count of a specific graph, the balanced complete
bipartite graph on $n$ vertices. We prove the identity
$\lceil n/2 \rceil \cdot \lfloor n/2 \rfloor = \lfloor n^2/4 \rfloor$ by a split
on parity, so that the phrase ``one edge above the Tur\'an threshold'' names an
object rather than a quantity.

Above that threshold the anti-Ramsey function for odd cycles falls into three
regimes as the cycle length grows: constant at $C_3$, linear at $C_5$, and
quadratic from $C_7$ onward. The three are a partition of the parameter, and the
linear formula falls below the quadratic one from $n = 8$, so the transition at
$k = 3$ is a change of order in $n$.
\end{abstract}

\section{The threshold is an edge count}

\begin{theorem}
\label{thm:turan}
For every $n$,
\[
  \boxed{\; \Big\lceil \frac n2 \Big\rceil \cdot \Big\lfloor \frac n2 \Big\rfloor
   \;=\; \Big\lfloor \frac{n^2}{4} \Big\rfloor . \;}
\]
\end{theorem}

\begin{proof}
Split on parity. If $n = 2m$ then the left side is $m \cdot m = m^2$ and the
right is $\lfloor 4m^2/4 \rfloor = m^2$.

If $n = 2m+1$ then the left side is $(m+1) \cdot m = m^2 + m$, while
$n^2 = 4m^2 + 4m + 1$, so the right side is
$\lfloor (4(m^2+m)+1)/4 \rfloor = m^2 + m$.
\end{proof}

\begin{corollary}
Mantel's extremal graph, the balanced complete bipartite graph
$K_{\lceil n/2 \rceil, \lfloor n/2 \rfloor}$, is triangle-free and has exactly
$\lfloor n^2/4 \rfloor$ edges.
\end{corollary}

Consequently ``one edge above the Tur\'an threshold'' names a specific
configuration: the balanced bipartite graph together with one edge placed inside
a part. Every such graph contains a triangle, and the anti-Ramsey question
concerns colourings of it.

\section{The anti-Ramsey function}

\begin{definition}
$\chi_S(n, e, H)$ is the least number of colours such that every colouring of an
$n$-vertex graph with $e$ edges using that many colours makes some copy of $H$
rainbow. The parameter of interest is
\[
  \chi_S\Big(n, \Big\lfloor \frac{n^2}{4} \Big\rfloor + 1, C_{2k+1}\Big).
\]
\end{definition}

\begin{theorem}[Regimes]
\label{thm:regimes}
As a function of $k$ the answer falls into three orders:
\[
  \chi_S \;=\;
  \begin{cases}
    3, & k = 1 \quad (C_3), \\[2pt]
    \lfloor n/2 \rfloor + 3, & k = 2 \quad (C_5), \\[2pt]
    \Theta(n^2/8), & k \ge 3 \quad (C_7 \text{ and beyond}).
  \end{cases}
\]
\end{theorem}

\begin{proposition}
\label{prop:partition}
The assignment of $k$ to its regime is a function whose three values partition
the positive integers: $k = 1$, $k = 2$, and $k \ge 3$. No $k$ receives two
regimes.
\end{proposition}

\begin{proof}
The three conditions are mutually exclusive and exhaustive on $k \ge 1$.
\end{proof}

\begin{proposition}
\label{prop:sep}
For $n \ge 8$,
\[
  8\Big( \Big\lfloor \frac n2 \Big\rfloor + 3 \Big) \;<\; n^2 ,
\]
so the linear formula lies strictly below $n^2/8$.
\end{proposition}

\begin{proof}
Since $8\lfloor n/2 \rfloor \le 4n$, the left side is at most $4n + 24$. From
$n \ge 8$ we get $n^2 \ge 8n = 4n + 4n \ge 4n + 32 > 4n + 24$.
\end{proof}

Together, \Cref{prop:partition} and \Cref{prop:sep} say that the three formulas
name three different orders on three disjoint ranges of the parameter, and that
they separate numerically from $n = 8$. The transition at $k = 3$ is a change of
order in $n$, from linear to quadratic.

\section{Position}

The asymptotic upper bound $n^2/8$ for $k \ge 4$ is due to Buci\'c, Chen and Ma.
The cases $C_3$ and $C_5$ are settled exactly. Sharp constants for $k \ge 4$, and
the classification for host graphs $H$ beyond odd cycles, remain open.

\section{Verification}

The edge-count identity, the partition of the parameter and the numerical
separation are formalised in \Lean{} against Mathlib, the identity by a split on
parity; all depend on \texttt{propext} and \texttt{Quot.sound}.

\begin{thebibliography}{9}
\bibitem{Mantel1907} W.~Mantel, \emph{Problem 28}, Wiskundige Opgaven
\textbf{10} (1907), 60--61.

\bibitem{Turan1941} P.~Tur\'an, \emph{On an extremal problem in graph theory}
(Hungarian), Mat.\ Fiz.\ Lapok \textbf{48} (1941), 436--452.

