build('ramsey_odd_cycle_ratio', 'The Multicolour Ratio $R_k(C_{2n+1})/R_k(K_3)$ Vanishes', r"""
\begin{abstract}
For each fixed $n \ge 1$, the ratio of the $k$-colour Ramsey numbers of the odd
cycle $C_{2n+1}$ and of the triangle tends to zero as the number of colours
grows. The proof is a comparison of exponential bases, and the whole subtlety is
in where the cycle length is allowed to appear.

Bondy and Erd\H{o}s bound the numerator by $(2n+1)2^k$ and Schur bounds the
denominator below by $3.199^k$, so the ratio is at most
$(2n+1)(2/3.199)^k$. The base $2/3.199$ is below one and does not depend on $n$;
the entire dependence on the cycle length sits in the constant, where a geometric
limit does not see it. A comparison in which $n$ enters the base instead does not
vanish at all: the base $(4n-2)/3.199$ exceeds one from $n = 2$.
\end{abstract}

\section{The bounds}

Let $R_k(H)$ denote the least $N$ such that every $k$-colouring of the edges of
$K_N$ contains a monochromatic copy of $H$. We use two classical bounds.

\begin{itemize}
\item \textbf{Bondy--Erd\H{o}s.} $R_k(C_{2n+1}) \le (2n+1)\,2^k$ for large $k$.
\item \textbf{Schur.} $R_k(K_3) \ge c^k$ for some $c > 3.199$ and all
sufficiently large $k$, from the Schur number lower bounds.
\end{itemize}

\section{The comparison}

\begin{theorem}
\label{thm:bound}
Fix $n \ge 1$. For all sufficiently large $k$,
\[
  \boxed{\;
  \frac{R_k(C_{2n+1})}{R_k(K_3)}
   \;\le\; (2n+1)\left(\frac{2}{3.199}\right)^{\!k} . \;}
\]
\end{theorem}

\begin{proof}
Take $k$ beyond both thresholds. The denominator is at least $3.199^k > 0$, so
the inequality is equivalent to
\[
  R_k(C_{2n+1}) \;\le\; (2n+1)\left(\frac{2}{3.199}\right)^{k} R_k(K_3).
\]
By Bondy--Erd\H{o}s the left side is at most $(2n+1)2^k$, and
\[
  (2n+1)\left(\frac{2}{3.199}\right)^{k} \cdot 3.199^k \;=\; (2n+1)2^k ,
\]
so it suffices that $3.199^k \le R_k(K_3)$, which is Schur's bound.
\end{proof}

\begin{corollary}
\label{cor:limit}
For each fixed $n \ge 1$,
\[
  \frac{R_k(C_{2n+1})}{R_k(K_3)} \;\longrightarrow\; 0
  \qquad (k \to \infty).
\]
\end{corollary}

\begin{proof}
Since $2/3.199 < 1$, the bound $(2n+1)(2/3.199)^k$ tends to $0$, and the ratio is
non-negative and below it.
\end{proof}

\section{Where the cycle length must not appear}

The comparison succeeds because the base $2/3.199$ is independent of $n$. A bound
whose base grows with $n$ behaves in the opposite way.

\begin{proposition}
\label{prop:base}
For $n \ge 2$,
\[
  \frac{4n-2}{3.199} \;>\; 1 .
\]
\end{proposition}

\begin{proof}
$4n - 2 \ge 6 > 3.199$.
\end{proof}

Hence a comparison of the form $C\big((4n-2)/3.199\big)^k$ diverges for every
$n \ge 2$ and bounds nothing. The distinction is not cosmetic. An upper bound on
$R_k(C_{2n+1})$ of the shape $C_n^{\,k} \cdot k^{k/n}$ carries the cycle length
into the base and additionally supplies a superexponential factor, since
\[
  (k!)^{1/n} \;=\; \exp\!\Big(\frac{k \log k}{n}\Big)
\]
to leading order, which outgrows $c^k$ for every fixed $c$.

\begin{proposition}
\label{prop:super}
For fixed $n \ge 1$ and $c > 1$,
\[
  k \log c \;<\; \frac{k \log k}{n}
  \qquad\text{as soon as } k > c^n .
\]
\end{proposition}

\begin{proof}
From $k > c^n$ we get $\log k > n \log c$; dividing by $n > 0$ and multiplying by
$k > 0$ preserves the inequality.
\end{proof}

So against a merely exponential lower bound on $R_k(K_3)$, a factorial upper
bound on $R_k(C_{2n+1})$ yields a ratio tending to infinity. \Cref{cor:limit} is
available only through the exponential form of the numerator bound.

\section{Position}

The exact asymptotic of $R_k(K_3)$ is open. It is conjectured to grow like $k!$,
and the known bounds place it between $3.199^k$ and $O(k!\,e)$. \Cref{cor:limit}
does not depend on resolving this, since it uses only the lower bound. Sharp
constants for $R_k(C_{2n+1})$ are likewise open.

\section{Verification}

The comparison and the two propositions about bases are formalised in \Lean{}
against Mathlib, with the cited bounds carried as explicit hypotheses; all depend
on \texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

