build('lcm_growth_density', '$\\operatorname{lcm}(1,\\dots,n)$ Exceeds $n\\log(n+1)$ from $n = 3$', r"""
\begin{abstract}
The least common multiple of the first $n$ integers grows like $e^n$, a fact
equivalent to the prime number theorem. Comparisons of that quantity against
polynomial or logarithmic expressions do not need the analytic result, and this
note isolates how little is required.

Two consecutive integers are coprime and both divide
$\operatorname{lcm}(1,\dots,n)$, so their product divides it too, giving the
elementary bound $\operatorname{lcm}(1,\dots,n) \ge n(n-1)$. Since
$\log(n+1) < n-1$ from $n = 3$, the inequality
$\operatorname{lcm}(1,\dots,n) > n \log(n+1)$ holds at every $n \ge 3$, and the
set of such $n$ has density one. A quadratic lower bound already outruns the
logarithmic comparison, several orders of magnitude short of the truth.
\end{abstract}

\section{A quadratic lower bound}

\begin{lemma}
\label{lem:quad}
For $n \ge 2$,
\[
  \boxed{\; n(n-1) \;\le\; \operatorname{lcm}(1, \dots, n). \;}
\]
\end{lemma}

\begin{proof}
Both $n$ and $n-1$ lie in $\{1, \dots, n\}$, so both divide
$L = \operatorname{lcm}(1, \dots, n)$. Consecutive integers are coprime, so their
product divides $L$ as well. Since $L > 0$, divisibility gives $n(n-1) \le L$.
\end{proof}

The true growth is $L = e^{(1+o(1))n}$ by the prime number theorem in
Chebyshev's form, but nothing below requires it.

\section{A logarithmic upper comparison}

\begin{lemma}
\label{lem:log}
For $n \ge 3$,
\[
  \log(n+1) \;<\; n - 1 .
\]
\end{lemma}

\begin{proof}
Equivalently $n + 1 < e^{\,n-1}$. Since $x + 1 \le e^x$ for all real $x$, taking
$x = n-2$ gives $n - 1 \le e^{\,n-2}$, whence
\[
  e^{\,n-1} \;=\; e^{\,n-2} \cdot e \;\ge\; (n-1)\,e \;>\; 2.7\,(n-1).
\]
For $n \ge 3$ the inequality $2.7(n-1) \ge n+1$ reduces to $1.7n \ge 3.7$, which
holds.
\end{proof}

\section{The comparison, and the density}

\begin{theorem}
\label{thm:main}
For every $n \ge 3$,
\[
  \boxed{\; \operatorname{lcm}(1, \dots, n) \;>\; n \log(n+1). \;}
\]
\end{theorem}

\begin{proof}
By \Cref{lem:log} we have $n\log(n+1) < n(n-1)$, and by \Cref{lem:quad} the
latter is at most $\operatorname{lcm}(1,\dots,n)$.
\end{proof}

\begin{corollary}
The set $\{\, n : \operatorname{lcm}(1,\dots,n) > n\log(n+1) \,\}$ contains every
integer from $3$ onward, so its density in $\{1, \dots, N\}$ tends to $1$.
\end{corollary}

\begin{remark}
The starting point is sharp. At $n = 2$ we have $\operatorname{lcm}(1,2) = 2$
against $2\log 3 \approx 2.197$, so the inequality fails; at $n = 3$ we have
$\operatorname{lcm}(1,2,3) = 6$ against $3\log 4 \approx 4.159$.
\end{remark}

\section{Position}

The sharp statements about $L_n = \operatorname{lcm}(1,\dots,n)$ are analytic.
Here $\log L_n = \psi(n)$ is Chebyshev's second function, the assertion
$\psi(n) \sim n$ is equivalent to the prime number theorem, and Rosser and
Schoenfeld's explicit bound gives $\psi(n) \le 1.04\,n$ for all $n \ge 1$.

The elementary bound of \Cref{lem:quad} is far weaker --- quadratic against
exponential --- and is nonetheless already sufficient to settle any comparison of
$L_n$ against a function of order $n\log n$.

\section{Verification}

The quadratic lower bound, the logarithmic comparison and their combination are
formalised in \Lean{} against Mathlib, with the numeric bound on $e$ taken from
the library; all depend on \texttt{propext}, \texttt{Classical.choice} and
\texttt{Quot.sound}.

