p='src/vox.rs'
s=open(p).read()
anchor = "fn is_work(g: char) -> bool"
assert anchor in s
add = '''/// Canonicalise the two spellings of the forward and reverse morphisms.
///
/// The Grammar's canonical twelve are `⊢ ⊣ > < ⋈ ⊤ ∈ ∋ ⊙ ⊥ ⊞ ◻`, and
/// `imasm_core::classic::Token::code` emits `>` and `<` accordingly, so every
/// word arriving from mOMonadOS or from a `Token` program is spelled that way.
/// V⊙x's own constants are `≻` and `≺`. Both spellings name the same two marks.
///
/// Without this, `∈>∋` and `∈≻∋` are the same word read two ways and get two
/// different verdicts — N and T — because `is_work` recognises only the second
/// pair, so an ASCII-spelled morphism silently contributes nothing and a word
/// that closes over real work reads as never having forked. Read at the parse
/// boundary, so the interior of the auditor sees one alphabet.
pub fn canonicalize(word: &[char]) -> Vec<char> {
    word.iter().map(|&c| match c {
        '>' => AFWD,
        '<' => AREV,
        other => other,
    }).collect()
}

'''
s = s.replace(anchor, add + anchor, 1)
open(p,'w').write(s)
print("vox.rs: canonicalize added")

