src = src.replace(
  "Words are read as loops, the last letter followed by the first. This is forced.",
  "Words are read as loops, the last letter followed by the first. This is forced.", 1)
src = src.replace(
  "Four readings, not two, and the two failures are not degrees of one another.",
  "Four readings, not two (\\Cref{fig:four}), and the two failures are not degrees of one another.", 1)
src = src.replace(
  "None of this is arrangeable after the fact.",
  "None of this is arrangeable after the fact (\\Cref{fig:invol,fig:boxes}).", 1)
src = src.replace(
  "So the reading is one integer and one question about it.",
  "So the reading is one integer and one question about it (\\Cref{fig:walk}).", 1)
src = src.replace(
  "They differ in the first base alone, adenine\ndividing and cytosine rejoining, with adenine fixed in the middle.",
  "They differ in the first base alone, adenine\ndividing and cytosine rejoining, with adenine fixed in the middle "
  "(\\Cref{fig:block}).", 1)
src = src.replace(
  "An\naccident does not put its parentheses there.",
  "An\naccident does not put its parentheses there (\\Cref{fig:glycan}).", 1)

io.open('life_compiled.tex','w',encoding='utf-8').write(src)
print("figures inserted:", src.count(r"\begin{figure}"))
