# -*- coding: utf-8 -*-
# One-shot splice of hand-written TikZ into the manuscript. The figures below are
# the source; nothing generates them afterwards.
import io
L = io.open('life_compiled.tex', encoding='utf-8').read().split('\n')

MARKTABLE = r"""
% The twelve marks, each bound once to the class it belongs to. Every figure that
% prints a word takes its colouring from this table, so no letter is coloured by
% hand and no figure can disagree with another about what a mark is.
\newcommand{\setmark}[2]{\expandafter\gdef\csname mk@c@#1\endcsname{#2}}
\newcommand{\mk}[1]{\textcolor{\csname mk@c@#1\endcsname}{\ig{#1}}}
\setmark{⊢}{cIdle}\setmark{⊣}{cIdle}\setmark{⊙}{cIdle}
\setmark{∈}{cDiv}\setmark{∋}{cFuse}
\setmark{≻}{cWork}\setmark{≺}{cWork}\setmark{⋈}{cWork}\setmark{⊤}{cWork}
\setmark{⊥}{cWork}\setmark{⊞}{cWork}\setmark{◻}{cWork}
"""

WALK = r"""\begin{figure}[htbp]
\centering
\begin{tikzpicture}[x=0.62cm,y=0.52cm,every node/.style={inner sep=1pt}]
  % One panel, drawn from the list of prefix balances and the letters that
  % produce them. Both panels are the same word. Only the starting index differs.
  \newcommand{\walkpanel}[3]{%
    \draw[black!15] (0,1) -- (6,1); \draw[black!15] (0,2) -- (6,2);
    \draw[black!45] (-0.2,0) -- (6.3,0);
    \draw[black!45] (0,-1.9) -- (0,2.5);
    \foreach \b [count=\i from 0, remember=\b as \prev (initially 0)] in {#1}{%
      \ifnum\i>0\relax \draw[very thick,#3] (\i-1,\prev) -- (\i,\b); \fi
      \fill (\i,\b) circle (1.7pt);}
    \foreach \c [count=\i from 1] in {#2}{\node at (\i-0.5,-2.6) {\mk{\c}};}}
  \begin{scope}
    \fill[cFuse!8] (0,-1.6) rectangle (6,0);
    \walkpanel{0,-1,-1,0,1,1,0}{∋,⋈,∈,∈,⋈,∋}{cIdle}
    \node[left,font=\scriptsize] at (-0.25,2) {$2$};
    \node[left,font=\scriptsize] at (-0.25,0) {$0$};
    \node[left,font=\scriptsize] at (-0.25,-1) {$-1$};
    \node[font=\small] at (3,3.5) {read from the start};
    \node[cFuse,font=\scriptsize,text width=3.3cm,align=center] at (3,-4.2)
      {a rejoining finds the stack empty};
  \end{scope}
  \begin{scope}[xshift=5.6cm]
    \walkpanel{0,0,1,2,2,1,0}{⋈,∈,∈,⋈,∋,∋}{cWork}
    \draw[cDiv,thick] (1.5,2.6) to[out=62,in=118] (5.5,2.6);
    \draw[cDiv,thick] (2.5,2.4) to[out=62,in=118] (4.5,2.4);
    \node[font=\small] at (3,4.4) {read from $k$, where $b$ is least};
    \node[cWork,font=\scriptsize,text width=3.6cm,align=center] at (3,-4.2)
      {every division answered, one region substantial};
  \end{scope}
  \draw[cWork,dashed,thick] (1,-2.0) -- (1,2.75);
  \node[cWork,font=\small\bfseries,above] at (1,2.75) {$k$};
\end{tikzpicture}
\caption[The reading point is determined]{The same word read twice. On the left the
reader begins where the sequence happens to begin, the running difference dips below
zero, and a rejoining answers nothing even though the word's two counts agree. On the
right the reader begins at the index where that difference is least, and from there it
never dips, so the pairing is total and the two regions nest. The cut is not chosen.
It is the argument of the minimum, and \Cref{lem:surplus} is the statement that
choosing it costs nothing and settles everything.}
\label{fig:walk}
\end{figure}"""

BOXES = r"""\begin{figure}[htbp]
\centering
\begin{tikzpicture}[x=1.62cm,y=1.16cm,font=\small]
  % The shading is not a list of exact boxes. Each base carries a value, and
