  % text, so the picture agrees with the genetic code only because the rule does.
  \node[font=\footnotesize\bfseries] at (1.9,0.72) {second base};
  \node[font=\footnotesize\bfseries,rotate=90] at (-1.42,-2.0) {first base};
  \foreach \nm/\vl/\i in {U/N/0,C/T/1,A/F/2,G/B/3}{%
    \node at (\i+0.5,0.3) {\nm~\tiny(\vl)};
    \node at (-0.75,-\i-0.5) {\nm~\tiny(\vl)};}
  \foreach \res/\fb/\sb in {%
    {Phe/Leu}/0/0,{Ser}/0/1,{Tyr/stop}/0/2,{Cys/stop/Trp}/0/3,%
    {Leu}/1/0,{Pro}/1/1,{His/Gln}/1/2,{Arg}/1/3,%
    {Ile/Met}/2/0,{Thr}/2/1,{Asn/Lys}/2/2,{Ser/Arg}/2/3,%
    {Val}/3/0,{Ala}/3/1,{Asp/Glu}/3/2,{Gly}/3/3}{%
    \pgfmathtruncatemacro{\isexact}{(\sb==1) || ((\sb==0 || \sb==3) && (\fb==1 || \fb==3))}%
    \ifnum\isexact=1\relax
      \draw[very thick,draw=cDiv,fill=cExact] (\sb,-\fb) rectangle (\sb+1,-\fb-1);
    \else
      \draw[thin,draw=black!35,fill=cSplit] (\sb,-\fb) rectangle (\sb+1,-\fb-1);
    \fi
    \node[font=\scriptsize] at (\sb+0.5,-\fb-0.5) {\res};}
  \node[font=\footnotesize,align=left,anchor=west] at (4.25,-0.75)
    {\textcolor{cDiv}{\textbf{exact}}: all four\\third bases agree};
  \node[font=\footnotesize,align=left,anchor=west] at (4.25,-2.4)
    {\textbf{split}: the third\\base is read};
  \draw[very thick,draw=cDiv,fill=cExact] (4.0,-0.9) rectangle (4.2,-0.6);
  \draw[thin,draw=black!35,fill=cSplit]   (4.0,-2.55) rectangle (4.2,-2.25);
\end{tikzpicture}
\caption[The degeneracy is a lattice theorem]{The sixteen boxes formed by the first two
bases, shaded by whether the third base changes the residue. Eight are exact and eight
are split, and which is which is not read off the table but follows from the values
alone: a box is exact when its second base is true, or when its second base is neither
or both while its first base is true or both. That rule is what draws the shading here,
and it agrees with the code on all sixteen. An exact box is $\mu \circ \delta =
\mathrm{id}$ at the codon level, the third base read and then forgotten with the
outcome unchanged, and the eight residues that occupy exact boxes are exactly the
backbone and packing residues that carry no instruction.}
\label{fig:boxes}
\end{figure}"""

ARCS = r"""\begin{figure}[htbp]
\centering
\begin{tikzpicture}[x=0.268cm,y=0.55cm,font=\footnotesize]
  % The word is written once, as letters. Each takes its colour from the class
  % table, so nothing here decides by hand what a mark is.
  \foreach \c [count=\i from 1] in
    {⊢,⋈,⊥,⊣,⋈,∈,⊙,⊞,⊥,⊤,≺,⋈,⊣,⊤,◻,∋,∈,∈,⊥,⊙,⊤,≺,∈,⊤,⊙,⋈,⊢,⊤,⋈,⋈,⊢,⊢,⊤,⊢,⊤,⋈,∈,⊣,⊢,⊤,⊥,⊢,⋈,⊢,∈,∈,⊢,⋈}%
    {\node at (\i,0) {\mk{\c}};}
  \draw[black!20] (0.4,-0.55) -- (48.6,-0.55);
  % the one region that closes inside this stretch
  \draw[very thick,cWork] (6,0.55) to[out=68,in=112] (16,0.55);
  \node[cWork,fill=white,inner sep=1.5pt] at (11,2.05) {answered, and substantial};
  % the divisions still on the stack when the stretch ends
  \foreach \p in {17,18,23,37,45,46}{%
    \draw[thick,cFuse,dash pattern=on 3pt off 2pt,-{Stealth}] (\p,-0.75) -- (\p,-2.1);}
  \draw[decorate,decoration={brace,amplitude=5pt,mirror},cFuse,thick]
     (16.4,-2.35) -- (46.6,-2.35);
  \node[cFuse,align=center] at (31.5,-3.4)
     {left open: the heme, the copper, the bilayer, the other subunits};
  \node[anchor=west,font=\scriptsize,cIdle] at (0.4,1.35) {first 48 letters of 226};
\end{tikzpicture}
\caption[An open reading, and where it is open]{The opening of the word emitted by
\textsc{mt-co1}. One division is answered inside this stretch and the region between
holds work, so it closes; six further divisions are pushed and never popped here, and
across the whole word eleven stand unanswered. A protein that hangs open is not a
broken protein. What answers those divisions is not in the chain, and the reading does
not merely report the failure to close, it names the position of every division whose
answer has to come from somewhere else.}
\label{fig:arcs}
\end{figure}"""

SWEEP = r"""\begin{figure}[htbp]
\centering
\begin{tikzpicture}[x=1cm,y=1cm,font=\footnotesize]
  % The bars are proportions, computed here from the raw counts, because the two
  % corpora differ in size by an order and only the shape is comparable.
  \def\barw{12.2}
  \newcommand{\segment}[5]{%
    \draw[draw=white,line width=0.7pt,fill=#1!30] (#2,#4) rectangle (#3,#4+0.84);
    \pgfmathsetmacro{\segw}{#3-#2}%
