    \fi}
  \newcommand{\sweeprow}[6]{%
    \pgfmathsetmacro{\tot}{#3+#4+#5+#6}%
    \node[anchor=west,align=left,font=\small] at (0,#1+1.22) {#2};
    \segment{cWork}{0}{\barw*#3/\tot}{#1}{#3}%
    \segment{cFuse}{\barw*#3/\tot}{\barw*(#3+#4)/\tot}{#1}{#4}%
    \segment{cIdle}{\barw*(#3+#4)/\tot}{\barw*(#3+#4+#5)/\tot}{#1}{#5}%
    \segment{cIll}{\barw*(#3+#4+#5)/\tot}{\barw}{#1}{#6}%
