\label{fig:sweep}
\end{figure}"""

def swap(a, b, block):          # 1-indexed, inclusive
    L[a-1:b] = block.split('\n')

swap(945, 985, SWEEP)
swap(663, 739, ARCS)
swap(371, 436, WALK)
swap(233, 292, BOXES)

for i, ln in enumerate(L):
